const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const RL=G.RESOURCE_LABELS,mat=G.materialLabel,raceName=s=>(s?.raceId&&Object.hasOwn(RACES,s.raceId)&&RACES[s.raceId].name)||s?.race||'';
const KEY='crown-calamity-v1',ROSTER_KEY='crown-calamity-roster-v1';let saveOK=true,saveRaw=null,rosterRaw=null;try{saveRaw=localStorage.getItem(KEY);rosterRaw=localStorage.getItem(ROSTER_KEY);}catch{saveOK=false;}
let roster=C.loadRoster(rosterRaw,saveRaw)||C.loadRoster(null,saveRaw)||C.emptyRoster(),state=C.activeCharacter(roster),firstRun=!state,view='hunt',huntTab='hunts',bagTab='gear',shopMode='buy',vendorId='weaponsmith',charTab='overview',worldTab='world',socialOpen=false,socialTab='chat',toastTimer,actionDelayTimer,exchangeFeedback=null,creationDraft=Creator.defaultCreationDraft(),creationInModal=false,identityDraft=null,recoveryTimer;if(!state)state=G.fresh();
function icon(k,cls=''){const path=Object.hasOwn(MENU_ICONS,k)?MENU_ICONS[k]:Object.hasOwn(UI_ICONS,k)?UI_ICONS[k]:UI_ICONS.spark;return `<svg class="icon menu-icon pixel-glyph ${cls}" viewBox="0 0 24 24" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true" focusable="false">${path}</svg>`;}
function enemyArt(e){return renderEnemyArt(e,{animated:!!state.fight&&state.fight.enemy===e.id});}
function itemArt(item,size='small'){return renderItemArt(typeof item==='string'?item:item?.id,{size});}
function save(){if(firstRun||!roster.activeId)return;try{C.saveActiveCharacter(roster,state);localStorage.setItem(ROSTER_KEY,JSON.stringify(roster));localStorage.setItem(KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function btn(action,text,cls='',disabled=false){const glyph={compare:'compare','buy-preview':'buy','sell-preview':'sell',upgrade:'upgrade','affix-menu':'reforge',exchange:'materials','character-manager':'characters',identity:'characters',respec:'attributes',export:'save',import:'save','open-gear':'gear','open-shop':'market','nav-abilities':'abilities'}[action.split(':')[0]];return `<button data-action="${esc(action)}" class="${cls}" ${disabled?'disabled':''}>${glyph&&!text.includes('<svg')?icon(glyph):''}${text}</button>`;}
function resolved(id){return G.resolveItem(state,id);}
function itemIcon(i){return ({weapon:i.focus?'staff':'sword',offhand:i.armor?'shield':'spark',head:'crown',body:'coat',hands:'shield',feet:'rest',accessory:'spark',accessory2:'spark',relic:'scroll'})[i.slot]||'spark';}
function nav(){return [['hunt','The adventure','hunt'],['story','Story & contracts','story'],['character','Character','character'],['bag','Satchel','bag'],['market','Quay market','market'],['journal','Chronicle','journal'],['world','World & community','guide'],['guide','Field guide','guide']];}
function recoveryButton(cls='resource-rest'){const r=G.restStatus(state),t=G.totals(state),full=state.hp>=t.hp&&state.mp>=t.mp&&state.sp>=t.sp;return btn('rest',`${icon('camp','status-art')} ${r.active?r.remainingMs>0?'Fluffing up · '+Math.ceil(r.remainingMs/1000)+'s':'Fluffing up… tap to finish':'Fluff up at the Quay · '+(G.REST_DURATION_MS/1000)+'s'} <span class="std">(Rest)</span>`,cls,!!state.fight||!!state.delve||(r.active?r.remainingMs>0:full));}
function recoveryHint(){const r=G.restStatus(state);return state.fight?'Available after this encounter.':state.delve?'Available after leaving the Laundry Works.':r.active?r.remainingMs>0?'A quiet fluff. Finish when ready.':'Ready. Tap to restore your Stuffing, Sparkle and Bounce.':r.wounded?'Drying off (Recovering): '+Math.ceil(r.remainingMs/1000)+'s before you can return.':state.hp>=G.totals(state).hp&&state.mp>=G.totals(state).mp&&state.sp>=G.totals(state).sp?'Fully fluffed. Save your breather for the canals.':(G.REST_DURATION_MS/1000)+' seconds, no coins. Basic attacks stay free.';}
function syncRecoveryUI(){clearTimeout(recoveryTimer);if(firstRun)return;const r=G.restStatus(state);if(r.remainingMs>0)recoveryTimer=setTimeout(()=>{if(!state.fight)render();},Math.min(1000,r.remainingMs+10));}
function focusEncounter(){if(typeof window.matchMedia==='function'&&window.matchMedia('(min-width: 741px)').matches){const controls=$('.combat-controls');controls?.scrollIntoView?.({block:'end',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}else window.scrollTo({top:0});}
function readCreationDraft(){const d={...creationDraft,appearance:{...creationDraft.appearance}},name=$('#new-name'),origin=$('#new-origin'),race=$('#new-race'),kit=$('#new-kit');if(name)d.name=name.value;if(origin)d.origin=origin.value;if(race?.value)d.race=race.value;if(kit?.value)d.kit=kit.value;for(const key of ['presentation','hairStyle','hairColor','eyeColor','skinTone']){const el=$('[data-creator-field="'+key+'"]');if(el?.value)d.appearance[key]=el.value;}creationDraft=Creator.normalizeCreationDraft(d);return creationDraft;}
function refreshCreator(){if(creationInModal&&!firstRun)newCharacterModal();else render();}
function resources(){const t=G.totals(state);return `<div class="resources" aria-label="Character resources">${[['hp','vitality'],['mp','flow'],['sp','vigor']].map(([k,ic])=>{const label=`${RL[k].name} (${RL[k].std})`;return `<div class="resource ${k}${k==='hp'&&exchangeFeedback?.incoming>0?' resource-hit':''}"><label><span class="resource-name">${icon(ic,'status-art')} <span class="resource-name-text">${RL[k].name.toUpperCase()}<small class="std">${RL[k].std}</small></span></span><span class="${k==='hp'&&state.hp<t.hp*.25?'health-warning':''}">${state[k]} <span class="muted">/ ${t[k]}</span></span></label><div class="bar" role="meter" aria-label="${label}" aria-valuemin="0" aria-valuemax="${t[k]}" aria-valuenow="${state[k]}"><i style="width:${Math.max(0,state[k]/t[k]*100)}%"></i></div></div>`;}).join('')}<div class="resource-recovery">${recoveryButton()}<small>${recoveryHint()}</small>${G.restStatus(state).active?btn('cancel-rest','Cancel fluffing up','text-button tiny'):''}</div></div>`;}
function shell(body,title,subtitle,eyebrow='CHAPTER I · FLUFFINGTON QUAY'){const combat=!!state.fight&&view==='hunt';return `<div class="shell bursar-shell"><aside class="sidebar"><div class="brand">${icon('crown')}<div class="wordmark">CROWN <span>&</span> CALAMITY</div></div><div class="nav-label">YOUR ADVENTURE</div><nav aria-label="Main navigation">${nav().map(([v,n,i])=>btn('nav:'+v,`${icon(i)}${n}${v==='character'&&state.points?`<span class="count">${state.points}</span>`:''}`,`nav-link ${view===v?'active':''}`)).join('')}</nav><div class="sidebar-footer"><div class="location">${icon('pin')} Fluffington Quay</div><p>The suds are rising.<br>The paperwork is not helping.</p>${recoveryButton('subtle')}<div class="version">SOLO PROTOTYPE · v0.11.0</div></div></aside><div class="page page--${view} ${combat?'in-combat':''}"><header class="topbar interface-header"><div class="bursar-interface"><img src="assets/hud/bursar-sigil.png" alt=""><span><strong>B.U.R.S.A.R.</strong><small>STUFFIE INTERFACE · LOCAL ARCHIVE</small></span></div><div class="place">${icon('pin')} <span>Fluffington Quay</span> <span>/</span><span>${{hunt:'The Lint Trap Canals',story:'Story contracts',character:'Character record',bag:'Personal effects',market:'Quay market',journal:'Adventure chronicle',guide:'Field guide',world:'World & community'}[view]}</span></div><div class="topbar-right"><button id="social-toggle" class="social-toggle" data-action="social-open:chat" aria-label="Open community drawer" aria-controls="social-drawer" aria-expanded="${socialOpen}">${icon('chat')}<span>Community</span></button><span class="save-label"><i class="save-dot"></i>${saveOK?'Local archive · saved on this browser':'Local archive · saving unavailable'}</span><span class="coins">${icon('coin')} ${state.coins.toLocaleString()}</span><button data-action="nav:character" class="identity-button" aria-label="Open character sheet"><span class="identity-name">${esc(state.name)}</span><span class="level-box" title="Level ${state.level}">${state.level}</span></button></div></header><main class="content" id="main"><div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><span class="chapter-seal"><i></i> A PROVISIONAL STUFFIE</span></div>${!saveOK?'<div class="error-banner">Browser saving is unavailable. Export a save from the Field Guide to keep your progress.</div>':''}${state.fight&&view!=='hunt'?`<div class="point-notice">An encounter is in progress. ${btn('nav:hunt','Return to encounter →')}</div>`:''}${resources()}${body}</main><footer class="footer"><span>CROWN & CALAMITY <span class="muted">/</span> AN ORIGINAL LITRPG</span><span>One tap. One exchange. Your next chapter.</span></footer></div></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav().filter(([v])=>!['guide','journal'].includes(v)).map(([v,n,i])=>btn('nav:'+v,`${icon(i)}<span>${{hunt:'Adventure',story:'Story',character:'Character',bag:'Satchel',market:'Market',journal:'Records',world:'World',guide:'Guide'}[v]}</span>${v==='character'&&state.points?'<span class="badge">!</span>':''}`,view===v||(['guide','journal'].includes(view)&&v==='world')?'active':'')).join('')}</nav>${renderSocialDrawer({tab:socialTab,open:socialOpen})}`;}
function titlePanel(label,body,cls=''){return `<section class="panel ${cls}"><div class="panel-label">${label}</div>${body}</section>`;}
function questPanel(){return renderStorySummary(state);}
const SLOT_ORDER=['weapon','offhand','head','body','hands','feet','accessory','accessory2','relic'];
const SLOT_LABELS={weapon:'Weapon',offhand:'Offhand',head:'Head',body:'Body',hands:'Hands',feet:'Feet',accessory:'Accessory',accessory2:'Second accessory',relic:'Relic'};
function equippedSlots(){return SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null,twoHanded=slot==='offhand'&&resolved(state.gear?.weapon)?.twoHanded,label=SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot,value=i?.name||(twoHanded?`Occupied by ${resolved(state.gear.weapon).name}`:'Empty');return `<div class="equipment-slot-row"><button data-action="slot:${slot}" class="slot-list-open" aria-label="${esc(label)} slot: ${esc(value)}. Review slot contents"><span class="slot-name">${esc(label)}</span>${i?itemArt(i):''}<span class="slot-equipped">${i?`<strong>${esc(i.name)}</strong><small>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</small>`:`<span class="empty-slot-label">${esc(value)}</span>`}</span></button>${i?btn('unequip-slot:'+slot,'Unequip','subtle tiny slot-unequip',!!state.fight||!!state.delve||!!G.unequipReason(state,slot)):''}</div>`;}).join('');}
function gearDiagram(){return `<div class="gear-diagram" role="group" aria-label="Equipment slots arranged around a generic body outline">${SLOT_ORDER.map(slot=>{const id=state.gear?.[slot],i=id?resolved(id):null,twoHanded=slot==='offhand'&&resolved(state.gear?.weapon)?.twoHanded,label=SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot,value=i?.name||(twoHanded?`Occupied by ${resolved(state.gear.weapon).name}`:'Empty');return `<button type="button" class="gear-slot-card slot-${slot} ${i?'filled':'empty'}" data-action="slot:${slot}" aria-label="${esc(label)} slot. ${esc(value)}. Activate to review or change"><span class="gear-slot-label">${esc(label)}</span>${i?itemArt(i):icon(({weapon:'sword',offhand:'shield',head:'crown',body:'coat',hands:'shield',feet:'rest',accessory:'spark',accessory2:'spark',relic:'scroll'})[slot])}<strong>${esc(value)}</strong><small>${i?itemStats(i).map(esc).join(' · ')||esc(i.desc):twoHanded?'Two-handed weapon occupies offhand':'Tap to view compatible gear'}</small></button>`;}).join('')}<div class="gear-figure" aria-hidden="true"><img src="assets/icons/adventurer-outline.png" width="120" height="280" alt=""><span>Equipment</span></div></div>`;}
function equipmentPanel(){return `<section class="panel equipment-panel"><div class="panel-label">YOUR EQUIPMENT · SELECT ANY SLOT</div>${gearDiagram()}<div class="equipment-list"><h3>Equipment list</h3><p class="tiny muted">Screen-reader and keyboard friendly slot list. Select a slot to compare or change what is equipped.</p>${equippedSlots()}</div></section>${RUI.renderRelicSockets(state)}`;}
function buildPanel(){return renderBuildSummary(state);}
