function pointNotice(){return state.points?`<div class="point-notice"><span>${icon('spark')} Level ${state.level} · <strong>${state.points} attribute point${state.points===1?'':'s'}</strong> to spend.</span>${btn('nav:character','Shape your build →')}</div>`:'';}
function huntChoice(){const unlocked=G.ENEMIES.filter(e=>e.id!=='boss'&&e.level<=state.level+2),contract=unlocked.find(e=>e.id===G.contractHuntTarget(state,id=>unlocked.some(e=>e.id===id)));return contract?{enemy:contract,why:'contract'}:{enemy:unlocked.find(e=>e.id===state.settings.lastHunt)||unlocked.at(-1),why:'last'};}
function hub(){const q=G.QUESTS[state.quest],choice=huntChoice(),target=choice.enemy,recovery=G.restStatus(state),unready=recovery.active||recovery.wounded||state.hp<=0;return `<div class="hero"><div class="hero-top"><span class="eyebrow">FLUFFINGTON QUAY · DISTRICT 01</span><span class="region-pill">HUNTING GROUNDS</span></div><div class="eyebrow">WELCOME TO THE LINT TRAP CANALS</div><h2>An honest day’s calamity.</h2><p>Fluffington Quay stays dry. Something below it doesn’t like that arrangement. Take a contract. Make a name. Mind the teeth, and your stuffing.</p><p class="care-label">NOTICE · Air quality: fuzzy. Proceed.</p><div class="hero-footer"><small>${icon('leaf')} ${G.storyState(state).stage===0?'Every adventure starts with a small problem.':choice.why==='contract'?'Advances your active contract · choose another below.':state.settings.lastHunt===target.id?'Return to your last hunt.':'Your toughest unlocked hunt · choose another below.'}</small>${G.storyState(state).stage===0?btn('nav:story','Meet Mara →','primary'):btn('hunt:'+target.id,'Hunt '+esc(target.name)+' →','primary',unready)}</div></div><div class="section-row"><h3>Choose your trouble</h3><small>One tap. One exchange.</small></div><div class="hunt-list">${G.ENEMIES.filter(e=>e.id!=='boss').map(e=>{const locked=e.level>state.level+2;return `<button class="hunt-row ${locked?'locked-row':''}" data-action="hunt:${e.id}" ${locked||unready?'disabled':''}>${enemyArt(e)}<div class="hunt-info"><div class="hunt-name">${esc(e.name)}</div><p>${esc(e.location)}${q?.target===e.id?' · Current contract':''}</p><div class="hunt-meta"><span>${e.hp} HP</span><span>${Math.floor((20+12*e.level)*(e.level-state.level<=-6?.25:e.level-state.level<=-3?.6:1))} XP</span><span>${e.coins} coins</span></div></div><span class="hunt-level">${locked?`UNLOCKS LV ${e.level-2}`:`LV ${e.level}`}</span>${icon(locked?'lock':'chevron','hunt-arrow')}</button>${renderVariantOffer(state,e,{disabled:locked||unready})}`;}).join('')}</div>${renderVariantProgress(state,G.ENEMIES.filter(e=>e.id!=='boss'&&e.level<=state.level+2))}<p class="bottom-note">${icon('shield')} ${recovery.active?'Finish or cancel your fluffing up before choosing a hunt.':recovery.wounded?'Still drying off (Recovering): '+Math.ceil(recovery.remainingMs/1000)+' more seconds.':state.hp<=0?'Fluff up at the Quay (Rest) before setting out again.':'Progress comes from your actions. The canals can wait for you.'}</p>`;}
function actionFeedback(){const r=exchangeFeedback;if(!r)return '<div class="battle-feedback battle-feedback--idle"><span>Your move. The canal has opinions.</span></div>';const label=r.critical?'Critical hit!':r.interrupted?'Interrupted!':r.healed>0?'A little better.':r.action==='recover'?'Shook it off.':r.damage>0?'A solid argument.':'Hunkered down!';const notes=[r.damage>0?`${r.damage} damage dealt`:null,r.healed>0?`${r.healed} Stuffing (health) restored`:null,r.manaRestored>0?`+${r.manaRestored} Sparkle (mana)`:null,r.incoming>0?`${r.heavy?'Heavy hit · ':''}${r.incoming} damage taken`:null,r.prevented>0?`${r.prevented} blocked`:null,r.absorbed>0?`${r.absorbed} absorbed`:null,r.opening?'Opening gained':null,r.openingUsed?'Opening used':null].filter(Boolean);return `<div class="battle-feedback battle-feedback--new ${r.critical?'is-critical':r.incoming>0?'is-impact':'is-steady'}" role="status"><strong>${icon(r.critical?'experience':r.healed>0?'vitality':r.incoming>0?'shield':'sword')}${label}</strong><span>${notes.map(esc).join(' · ')||'One exchange. Nicely accounted for.'}</span></div>`;}
function combatView(){const f=state.fight,e=G.fightEnemy(f),intent=G.intent(state),A=G.ABILITIES||{},main=G.mainActionKeys?G.mainActionKeys(state):G.primaryActions?G.primaryActions(state):{skill:'cast',combined:'combo'};const secondary=[...(state.equippedAbilities||[]).map(id=>[id==='arc'?'cast':id,A[id]?.name||id]),['recover','Recover'],...(e.id==='boss'&&f.hp<e.hp*.65&&!f.vented?[['vent','Vent']]:[]),['withdraw','Withdraw']];const primaryKeys=new Set(['attack',main.skill,main.combined,'guard']);const seen=new Set(),defs=[];for(const key of ['attack',main.skill,main.combined,'guard'])if(!seen.has(key)){seen.add(key);defs.push(key);}for(const key of ['recover','withdraw','vent'])if(defs.length<4&&!seen.has(key)){seen.add(key);defs.push(key);}const keyIcon={attack:'sword',cast:'bolt',combo:'spark',driving:'sword',guardstrike:'shield',guard:'shield',brace:'shield',disrupt:'sword',mend:'cross',aegis:'shield',expose:'spark',recover:'rest',vent:'settings',withdraw:'exit'};return `<section class="encounter bursar-stage ${exchangeFeedback?.critical?'battle-critical':exchangeFeedback?.damage>0?'battle-hit':''}"><div class="encounter-top"><div class="stage-readout"><div class="eyebrow">${esc(e.location.toUpperCase())} · EXCHANGE ${f.round+1}</div><h2>${esc(e.name)}</h2><p>${esc(e.blurb)}</p><div class="encounter-badges"><span>LEVEL ${e.level}</span><span>ARMOR ${e.armor}</span><span>WARD ${e.ward}</span></div>${renderVariantBanner(f,e)}</div>${enemyArt(e)}</div>${actionFeedback()}<div class="enemy-health"><label><span>ENEMY HEALTH</span><span>${f.hp} / ${e.hp}</span></label><div class="bar" role="meter" aria-label="Enemy health" aria-valuemin="0" aria-valuemax="${e.hp}" aria-valuenow="${f.hp}"><i style="width:${f.hp/e.hp*100}%"></i></div></div><div class="intent ${intent.heavy?'heavy':''}">${icon(intent.heavy?'bolt':'shield')}<div><strong>${esc(intent.name)}</strong><small>${intent.heavy?G.telegraphText.heavyHint():'The enemy responds after your action.'} ~${intent.damage} raw damage.</small></div>${f.charge||f.opening?`<span class="intent-badges">${f.charge?'<span class="hunt-level gold">RESERVOIR +10%</span>':''}${f.opening?`<span class="hunt-level gold">${G.openingLabel(f,state.mastery?.expose?.rank)}</span>`:''}</span>`:''}</div></section><div class="combat-controls rune-console" aria-label="Combat actions" tabindex="-1"><div class="combat-timing action-recovery"><div class="recovery-heading">${icon('clock')}<span id="action-ready-text" role="status" aria-live="polite">Ready for your next action</span><span id="action-delay-count">Ready</span></div><span id="action-delay-track" class="action-delay-track" role="progressbar" aria-label="Action recovery" aria-valuemin="0" aria-valuemax="${G.ACTION_DELAY_MS}" aria-valuenow="${G.ACTION_DELAY_MS}"><i></i></span></div><div class="action-grid">${defs.map((k,index)=>{const a=G.actionInfo(state,k)||{label:k,cost:'',desc:''};return `<button class="action-btn ${index===2?'preferred':''}" data-action="combat:${k}" ${a.reason?'disabled':''} title="${esc(a.reason||a.desc)}" aria-label="${esc(a.label)}${a.std?` (${esc(a.std)})`:''}. ${esc(a.reason||a.desc)}">${icon(keyIcon[k]||'spark')}<span>${esc(a.label)}</span><small>${a.std?esc(a.std)+' · ':''}${esc(a.cost)}</small></button>`;}).join('')}</div><div class="secondary-actions">${secondary.filter(([k])=>!primaryKeys.has(k)).map(([k,label])=>{const a=G.actionInfo(state,k)||{label:label,cost:'',desc:''};return btn('combat:'+k,`${icon(keyIcon[k]||'spark')}${esc(a.label||label)}${a.std?` <span class="std">(${esc(a.std)})</span>`:''}${(f.cooldowns[k]||0)>f.round?` · ${f.cooldowns[k]-f.round}`:''}`,'',!!a.reason);}).join('')}</div><div class="combat-hint">+${G.MANA_REGEN_PER_EXCHANGE} Sparkle (mana) after any action that spends none. Shake it off (Recover) restores ${G.RECOVER_MANA_RESTORE+G.MANA_REGEN_PER_EXCHANGE} Sparkle (mana) and 10 Bounce (stamina).</div></div>${report()}`;}
function report(){return renderEncounterRecord(state);}
function outcome(){return renderEncounterOutcome(state,{celebrate:!!exchangeFeedback})+pointNotice()+report();}
function delveView(){if(!state.delve)return `<div class="hero"><div class="hero-top"><span class="eyebrow">THE LAUNDRY WORKS</span><span class="region-pill">SOLO DELVE · LV 6+</span></div><div class="eyebrow">A VOLUNTARY BAD IDEA</div><h2>Someone has to go below.</h2><p>Five checkpoints. One camp. A washer with authority issues. Take your prepared build into the Laundry Works.</p><p class="care-label">NOTICE · Delicates, this way. Everyone else: good luck.</p><div class="hero-footer"><small>Completed room rewards stay yours.</small>${btn('delve-start',state.level<6?'Unlocks at level 6':!state.clears&&!G.contractStatus(state,'municipal_works').active&&!G.contractStatus(state,'municipal_works').completed?'Accept the major contract first':'Enter the Laundry Works →','primary',state.level<6||state.hp<=0||(!state.clears&&!G.contractStatus(state,'municipal_works').active&&!G.contractStatus(state,'municipal_works').completed))}</div></div><section class="panel" style="margin-top:20px"><h3>Know what you’re signing.</h3><p class="muted">Equipment and attributes lock during the delve. You get one full recovery at camp. Every exchange still needs your input. Returning to town ends this run and resets the camp.</p><p class="muted">${btn('nav:story','Review story requirements →','text-button')}</p><p class="muted no-margin">The Spin Cycle unlocks a guaranteed first-clear item choice. The ordinary hunting grounds remain available.</p></section>`;
const d=state.delve;return `<section class="panel"><div class="eyebrow">THE LAUNDRY WORKS · SOLO EXPEDITION</div><div class="delve-path">${['Maintenance door','Crossroads','Chosen route','One camp','The Drum'].map((n,j)=>`<div class="delve-node ${j<d.node?'done':j===d.node?'current':''}">${j+1}. ${n}</div>`).join('')}</div>${d.node===0?`<h2>The maintenance door</h2><p class="muted">A Clawback Crab blocks the maintenance entrance. Its slow grab winds up slowly. A spell goes through its armor rather nicely.</p>${btn('delve:enter','Clear the maintenance door →','primary')}`:d.node===1?`<h2>Two ways to help.</h2><p class="muted">The Seam Crew is somewhere below. The Lost & Found Ledger might say where they were tagged. But the Drain Valve is failing, too.</p><div class="choices">${btn('delve:records','<strong>Recover the Lost & Found Ledger</strong><small>Face the Lost & Found Appraiser. Find evidence of the missing Seam Crew.</small>','choice')}${btn('delve:overflow','<strong>Secure the Drain Valve</strong><small>Face Chewster, the Family Dog. Protect the homes along the canal.</small>','choice')}</div><p class="tiny muted">Both routes reach the camp and boss. Your choice is recorded in the Chronicle.</p>`:d.node===3?`<h2>A moment above the suds.</h2><p class="muted">A dry maintenance shelf. A thimble of tea. Nothing trying to eat you. You have ${d.campUsed?'used your recovery charge':'one full recovery available'}.</p><div class="outcome-actions">${btn('delve:rest',d.campUsed?'Camp used':'Use camp recovery','subtle',d.campUsed)}${btn('delve:continue','Face The Spin Cycle →','primary')}</div>`:'<h2>The Laundry Works are waiting.</h2>'}<p class="mechanics">${btn('delve-leave','Return to town · end this run','text-button')}</p></section>`;}
function huntView(){return shell(`<div class="layout"><div class="main-column">${!state.fight?`<div class="tabs">${btn('tab:hunts',`${icon('hunt')} Hunting grounds`,huntTab==='hunts'?'active':'')}${btn('tab:delve',`${icon('lock')} Laundry Works`,huntTab==='delve'?'active':'')}</div>`:''}${state.fight?combatView():state.last?outcome():`${pointNotice()}${huntTab==='delve'?delveView():hub()}`}</div>${rightSide()}</div>`,'Below the Rinse Line','A small town. A very large washer. A growing list of problems.');}
const percent=v=>(v*100).toFixed(2)+'%';
const STAT_NAMES={heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',hp:'Max Stuffing (Health)',mp:'Max Sparkle (Mana)',sp:'Max Bounce (Stamina)',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops',mendHealing:'Mend healing'};
function attributeEffect(k){
 const p=G.attributePreview(state,k);
 return p.changes.map(c=>`${STAT_NAMES[c.field]} ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.before):c.before} → ${['critChance','equipmentDropChance'].includes(c.field)?percent(c.after):c.after}`).join(' · ');
}
function buildInspector(){
 const t=G.totals(state),id=state.fight?.enemy||(G.ENEMIES.some(e=>e.id===state.settings.inspectTarget)?state.settings.inspectTarget:G.ENEMIES.filter(e=>e.level<=state.level).at(-1)?.id)||'rats',enemy=G.ENEMIES.find(e=>e.id===id),w=resolved(state.gear.weapon);
 const physicalMitigation=G.mitigation(t.armor,enemy.level),arcaneMitigation=G.mitigation(t.ward,enemy.level),enemySolidHit=G.hitChance(25+4*enemy.level,t.evasion);
 return `<section class="panel stats-inspector"><div class="panel-label">BUILD INSPECTOR · ACTUAL COMBAT RULES</div><h3>Know what your build does.</h3><p class="muted">Your ${w.name} uses <strong>${w.channel==='spell'?'Intellect':w.channel==='precision'?'Finesse':'Might'}</strong> for Attack. Compare a target before spending points or changing equipment.</p><label class="inspect-target" for="inspect-target">Compare against<select id="inspect-target" ${state.fight?'disabled':''}>${G.ENEMIES.map(e=>`<option value="${e.id}" ${e.id===id?'selected':''}>${esc(e.name)} · level ${e.level}</option>`).join('')}</select></label><div class="derived-grid">${[['Heavy power',t.heavyPower],['Precision power',t.precisionPower],['Spell power',t.spellPower],['Physical accuracy',t.physicalAcc],['Spell accuracy',t.spellAcc],['Evasion',t.evasion],['Critical chance',percent(t.critChance)],['Critical damage','125%'],['Mend healing',t.mendHealing],['Physical reduction',percent(physicalMitigation)],['Arcane reduction',percent(arcaneMitigation)],['Enemy glancing chance',percent(1-enemySolidHit)]].map(([n,v])=>`<div class="derived-stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><p class="inspector-context">${state.fight?'Current encounter: includes the enemy’s stance, stored charge, and any adaptation.':'Neutral stance: excludes encounter-only Guard, wards, Reservoir charges, and boss openings.'} Reduction and accuracy depend on the selected enemy. Critical chance applies to solid hits.</p><p class="inspector-context">${G.telegraphText.heavyGuard()} ${G.telegraphText.ceiling()}</p><div class="damage-profiles">${[['attack','Attack','Free'],['cast','Arc Bolt',G.actionInfo(state,'cast').cost],['combo','Wardcast',G.actionInfo(state,'combo').cost+' + Guard'],...(G.primaryActions(state).combined==='sidestep'?[['sidestep','Sidestep',G.actionInfo(state,'sidestep').cost+' + Guard']]:[])].map(([key,label,cost])=>{const a=G.actionProfile(state,key,id);return `<div class="damage-profile"><div class="flex-between"><h4>${label}</h4><span>${a.available?cost:'Requires '+(key==='combo'?'a focus & shield':key==='sidestep'?'a precision weapon & no shield':'a focus')}</span></div><dl><div><dt>Normal / critical / glancing</dt><dd>${a.normal} / ${a.critical} / ${a.glance}</dd></div><div><dt>Solid-hit chance</dt><dd>${percent(a.hitChance)}</dd></div><div><dt>Average per action</dt><dd>${a.average.toFixed(1)} ${a.channel}</dd></div>${a.opening?`<div><dt>Opening</dt><dd>+${Math.round(a.openingBonus*100)}% · cannot glance</dd></div>`:''}</dl>${!a.available?'<p class="muted">Preview only; this action is unavailable with your equipment.</p>':''}</div>`;}).join('')}</div></section><section class="panel fortune-panel"><div class="panel-label">LUCK · SMALL EDGES, REAL EFFECTS</div><h3>Fortune has rules.</h3><div class="derived-grid"><div class="derived-stat"><span>Total Luck</span><strong>${t.lck}</strong></div><div class="derived-stat"><span>Equipment-drop chance</span><strong>${percent(t.equipmentDropChance)}</strong></div></div><p>Luck above 8 improves critical chance and equipment drops with diminishing returns. A Copper-Thread Charm adds +4 Luck and is available from The Odds & Ends Drawer (Curio dealer) for 25 coins.</p><p class="muted">Guaranteed XP, coins, materials, and first-boss rewards stay guaranteed. Luck never grants extra exchanges or bypasses the action delay. Duplicate equipment drops become Spare thread.</p>${btn('shop-luck','Visit The Odds & Ends Drawer →','text-button')}</section>`;
}
function tabButton(id,label){return btn('char-tab:'+id,`${icon(id)}${label}`,charTab===id?'active':'');}
function requirementsView(req,raw={}){if(!req)return '';const rows=[];if(req.level?.required>0)rows.push(`Level ${state.level} / ${req.level.required}`);if(raw.questOrGuards){const needQ=req.quest?.required||raw.quest||0,needG=req.usefulGuards?.required||raw.usefulGuards||0,met=!!(req.quest?.met||req.usefulGuards?.met);if(needQ||needG)rows.push(`${met?'Met · ':''}${needQ} contracts or ${needG} useful Guards`);}else if(req.quest?.required>0)rows.push(`Contracts ${state.quest} / ${req.quest.required}`);if(req.guardCount?.required>0)rows.push(`Useful Guards ${state.guardCount||0} / ${req.guardCount.required}`);if(req.usefulGuards?.required>0&&!raw.questOrGuards)rows.push(`Useful Guards ${state.usefulGuards||0} / ${req.usefulGuards.required}`);return rows.length?`<div class="requirement-list"><strong>Requirements</strong>${rows.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:'';}
function abilityScreen(){
 const A=G.ABILITIES||{},ids=Object.keys(A),active=ids.filter(id=>A[id].kind==='active'),passives=ids.filter(id=>A[id].kind==='passive'),used=G.attunementUsed?G.attunementUsed(state):0,locked=!!state.fight||!!state.delve;
 const card=id=>{const a=A[id],st=G.abilityStatus(state,id)||{},mastery=st.mastery||state.mastery?.[id]||a.mastery||{},passiveOverflow=a.kind==='passive'&&used-(A[state.passive]?.kind==='passive'?A[state.passive].attunement:0)+(a.attunement||0)>6,activeOverflow=a.kind==='active'&&!st.equipped&&used+(a.attunement||0)>6,slotOverflow=a.kind==='active'&&!st.equipped&&(state.equippedAbilities||[]).length>=3,equipBlock=passiveOverflow?'Exceeds the 6-point attunement limit.':activeOverflow?'Exceeds the 6-point attunement limit.':slotOverflow?'All three active slots are occupied.':'';return `<article class="ability-card ${st.equipped?'equipped':''} ${!st.learned?'ability-locked':''}"><div class="ability-card-head"><div><span class="eyebrow">${a.kind==='passive'?'PASSIVE':'ACTIVE'} · ${a.attunement||0} ATTUNEMENT</span><h3>${esc(a.name)}</h3></div><span class="ability-state">${st.equipped?'Equipped':st.learned?'Learned':'Locked'}</span></div><p>${esc(a.desc||'')}</p>${a.focus?'<p class="ability-focus">Requires a focus-capable weapon or offhand to use Arc Bolt.</p>':''}${requirementsView(st.requirements,a.requires)}${!st.eligible&&st.reason?`<p class="ability-reason">${esc(st.reason)}</p>`:''}${st.learned&&!st.equipped&&equipBlock?`<p class="ability-reason">${esc(equipBlock)}</p>`:''}${a.kind==='active'?`<div class="ability-meta">Cost: ${G.costLabel(G.abilityCost(id,state.mastery))} <span>Mastery rank ${mastery.rank||1} · ${mastery.marks||0} marks</span></div>`:''}${st.learned?(a.kind==='active'?btn(st.equipped?'ability-remove:'+id:'ability-equip:'+id,st.equipped?'Remove from active bar':'Equip ability','subtle',locked||(!st.equipped&&(!st.learned&&!st.eligible||!!activeOverflow||!!slotOverflow))):`<div class="ability-meta">Passive slot ${state.passive===id?'· Equipped':'· Select one'}</div>${btn(state.passive===id?'ability-remove:'+id:'ability-equip:'+id,state.passive===id?'Unequip passive':passiveOverflow?'Exceeds attunement':'Equip passive','subtle',locked||passiveOverflow&&state.passive!==id)}`):btn('ability-learn:'+id,st.eligible?'Learn ability':'Requirements not met','',locked||!st.eligible)}</article>`;};
 const masteryChoices=active.map(id=>{const st=G.abilityStatus(state,id)||{},m=st.mastery||{};if((m.rank||0)<3)return '';const choices=m.choices||[];return `<section class="mastery-card"><div class="flex-between"><div><span class="eyebrow">RANK 3 MASTERY</span><h3>${esc(A[id].name)}</h3></div><span class="hunt-level">${(m.rank3Choice||m.choice)?'CHOICE SET':'CHOOSE ONE'}</span></div><p>Choose the behavior that fits your build. The engine will apply the selected rank 3 effect.</p>${choices.map(c=>{const key=typeof c==='string'?c:c.id||c.key,label=typeof c==='string'?({economy:'Economy',power:'Power',barrier:'Larger barrier',recovery:'Faster recovery',immunity:'Shorter immunity',healing:'Greater healing'})[c]||c:c.name||c.label||key,desc=(m.descriptions||{})[key]||(typeof c==='string'?'':c.desc||c.description||'');return `<button data-action="mastery:${id}:${esc(key)}" class="mastery-choice ${(m.rank3Choice||m.choice)===key?'selected':''}" ${locked?'disabled':''}><strong>${esc(label)}</strong><small>${esc(desc)}</small></button>`;}).join('')}</section>`;}).join('');
 return `<div class="ability-overview"><div class="capacity-card"><strong>Attunement ${used} / 6</strong><span>${(state.equippedAbilities||[]).length} / 3 active slots · 1 passive slot</span></div><p class="muted">Learn abilities as you meet their listed requirements. Equip up to three active abilities; only equipped actions appear during combat. Rank progress comes from eligible victories.</p>${locked?'<div class="point-notice">Abilities are locked during an encounter or expedition.</div>':''}</div><section><div class="section-row"><h2>Active abilities</h2><small>Only equipped actions enter combat</small></div><div class="ability-grid">${active.map(card).join('')}</div></section><section><div class="section-row"><h2>Passive abilities</h2><small>One equipped</small></div><div class="ability-grid">${passives.map(card).join('')}</div></section>${masteryChoices?`<section><div class="section-row"><h2>Mastery choices</h2></div><div class="mastery-grid">${masteryChoices}</div></section>`:''}${Object.entries(state.mastery||{}).length?`<section class="panel mastery-progress"><div class="panel-label">MASTERY PROGRESS</div>${Object.entries(state.mastery).map(([id,m])=>`<div class="loadout-item"><div><b>${esc(A[id]?.name||id)}</b><small>${m.rank>=3?'Rank 3 · Prototype cap':`${m.marks} / ${3+2*m.rank} qualifying victories to rank ${m.rank+1}`}</small></div><span class="hunt-level">RANK ${m.rank}</span></div>`).join('')}</section>`:''}`;
}
function characterManager(){const locked=!C.rosterCanChange(roster,state);modal('Your stuffies',`<p>${roster.characters.length} of ${C.MAX_CHARACTERS} character slots used. Create or switch characters without removing any existing adventure.</p><div class="character-list">${roster.characters.map(entry=>{const s=entry.state,active=entry.id===roster.activeId;return `<div class="character-list-row"><div><strong>${esc(s.name)}</strong><small>${esc(raceName(s))} · Level ${s.level} · ${esc(s.origin)}</small></div>${active?'<span class="active-character-tag">Active</span>':btn('switch-character:'+entry.id,'Switch','subtle',locked)}</div>`;}).join('')}</div>${roster.characters.length>=C.MAX_CHARACTERS?'<p class="ability-reason">All six character slots are in use. Export a save before clearing anything; character deletion is not available here.</p>':''}<div class="modal-actions">${btn('new-character-form','Create character','primary',locked||roster.characters.length>=C.MAX_CHARACTERS)}${btn('close','Done','subtle')}</div>`, 'CHARACTER ROSTER');}
function newCharacterModal(){creationInModal=true;modal('Create another stuffie',Creator.renderCharacterCreator({draft:creationDraft,modal:true,canCreate:roster.characters.length<C.MAX_CHARACTERS&&!state.fight&&!state.delve})+btn('close','Cancel','text-button'),'NEW LOCAL CHARACTER');}
function earnedAttributeBudget(s){const p=G.progression(s);return 68+4*(s.level-1)+(p?.part||s.part||1)-1;}
function levelProgressPanel(){const p=G.progression(state);if(!p)return '';const capped=!!p.capped,levelPercent=capped?100:Math.max(0,Math.min(100,p.levelXP/p.levelRequired*100)),partPercent=capped?100:Math.max(0,Math.min(100,p.partXP/p.partRequired*100));return `<section class="panel progression-panel"><div class="progression-head"><div><div class="eyebrow">CHARACTER PROGRESSION</div><strong>Level ${p.level} · Stitch ${p.part} of ${p.parts} <small class="std">(level part)</small></strong></div><span>${p.totalEarned} attribute points earned</span></div><div class="xp-track"><label><span>FULL LEVEL PROGRESS</span><span>${capped?'PROTOTYPE CAP':`${p.levelXP} / ${p.levelRequired} XP`}</span></label><div class="bar" role="meter" aria-label="Level experience" aria-valuemin="0" aria-valuemax="${p.levelRequired||1}" aria-valuenow="${p.levelXP}"><i style="width:${levelPercent}%"></i></div></div><div class="part-track-label"><span>ATTRIBUTE MILESTONE ${capped?'COMPLETE':`· STITCH ${p.part} / ${p.parts} (LEVEL PART)`}</span><span>${capped?'No further points at the prototype cap':`${p.partXP} / ${p.partRequired} XP · Next: +1 attribute point`}</span></div><div class="part-track" aria-label="Stitch ${p.part} of ${p.parts} (level part); ${p.partXP} of ${p.partRequired} experience to the next attribute point">${Array.from({length:p.parts},(_,i)=>`<span class="${i+1<p.part?'complete':i+1===p.part&&!capped?'current':''}" ${i+1===p.part&&!capped?`aria-current="step"`:''}>${i+1===p.part&&!capped?`<i style="width:${partPercent}%"></i>`:''}</span>`).join('')}</div></section>`;}
function characterView(){const t=G.totals(state),locked=!!state.fight||!!state.delve,selected=state.gear.weapon;const tabs=`<div class="tabs sheet-tabs" role="tablist" aria-label="Character sheet">${tabButton('overview','Overview')}${tabButton('attributes',`Attributes${state.points?` · ${state.points}`:''}`)}${tabButton('abilities','Abilities')}${tabButton('gear','Gear')}</div>`;
 const overview=renderCharacterOverview(state,{levelProgressHTML:levelProgressPanel(),inspectorHTML:buildInspector()});
 const attributes=`<section class="panel"><div class="panel-label"><span>YOUR ATTRIBUTES</span><span class="gold">${state.points} POINTS AVAILABLE</span></div>${locked?'<p class="tiny muted">Attribute changes are locked during an encounter or expedition.</p>':'<p class="tiny muted">Seven attributes. Every point has an inspectable effect. Luck starts at 8; use a free respec to try a different investment.</p>'}<div class="attributes">${Object.entries(G.ATTRS).map(([k,[name,description]])=>`<div class="attribute"><span class="attr-code">${k.toUpperCase()}</span><div><b>${name}</b><span class="attribute-description">${description}</span><small>${attributeEffect(k)}</small><span class="attribute-source">Invested ${state.stats[k]} + gear ${t.gearBonuses[k]} = ${t[k]}</span></div><span class="attr-value">${t[k]}</span><button data-action="stat:${k}" aria-label="Add one point to ${name}" ${locked||state.points<=0?'disabled':''}>${icon('plus')}</button></div>`).join('')}</div><div class="flex-between" style="margin-top:12px"><span class="tiny muted">Budget ${earnedAttributeBudget(state)} · Invested ${Object.values(state.stats).reduce((a,b)=>a+b,0)} · Unspent ${state.points}</span>${btn('respec','Reallocate points →','text-button tiny',locked)}</div></section><section class="panel"><div class="panel-label">PRACTICE LOADOUTS · NOT CLASSES</div><p class="tiny muted">Try an arrangement. Every attribute, item and ability stays open to you.</p><div class="kit-grid">${[['bulwark','Rod & shield','Intellect · durable casting',selected==='rod'&&state.gear.offhand==='shield'],['caster','Rod & focus','Intellect · spell output',selected==='rod'&&state.gear.offhand==='focus'],['duelist','Blade & charm','Finesse · accuracy',selected==='blade'],['breaker','Sword & shield','Might · physical pressure',selected==='sword']].map(([id,n,d,sel])=>btn('kit:'+id,`${n}<small>${d}</small>`,`kit ${sel?'selected':''}`,locked)).join('')}</div></section>`;
 return shell(`<div class="main-column character-sheet">${tabs}${charTab==='attributes'?attributes:charTab==='abilities'?abilityScreen():charTab==='gear'?equipmentPanel():overview}</div>`,'A build of your own','Resources, attributes, equipment, and abilities in one readable record.','CHARACTER RECORD · FLUFFINGTON QUAY');}
function itemStats(i){return [i.base?`${i.base} base`:null,i.armor?`${i.armor} armor`:null,i.ward?`${i.ward} ward`:null,i.spellBase?`${i.spellBase} spell base`:null,...Object.entries(i.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`),i.upgrade?`+${i.upgrade} upgrade`:null,i.prefix?G.PREFIXES?.[i.prefix]?.name:null,i.suffix?G.SUFFIXES?.[i.suffix]?.name:null,i.id==='seal'?'15 barrier on useful Guard':null].filter(Boolean);}
function compare(id,targetSlot=null){const i=resolved(id),choices=G.slotChoices(state,id),selected=targetSlot||choices[0]||null,owned=state.bag.includes(id),eq=selected?state.gear[selected]===id:Object.values(state.gear).includes(id),oldId=selected?state.gear[selected]:state.gear[i.slot],old=oldId?resolved(oldId):null;const slotCards=!targetSlot&&choices.length>1?`<div class="target-slot-choices"><strong>Choose a slot</strong>${choices.map(slot=>{const current=state.gear[slot]?resolved(state.gear[slot]):null;return `<button data-action="equip:${id}:${slot}" class="slot-choice" ${state.fight||state.delve?'disabled':''}><span>${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot}</span><small>Replaces ${current?.name||'Empty'}</small></button>`;}).join('')}</div>`:'';modal(i.name,`<p>${esc(i.desc)}</p><div class="compare"><div><span class="eyebrow">CURRENTLY EQUIPPED · ${esc(SLOT_LABELS[selected]||G.SLOTS?.[selected]||selected||i.slot)}</span>${old?itemArt(old,'large'):''}<h3>${esc(old?.name||'Empty slot')}</h3><p>${old?itemStats(old).map(esc).join('<br>'):'No item in this slot.'}</p></div><div><span class="eyebrow">THIS ITEM · LEVEL ${i.level}</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'An authored equipment trait.'}</p></div></div>${equipmentEffectPreview(id,selected)}${i.slot==='weapon'&&i.channel!=='spell'?`<p class="modal-help">Physical weapon skills do not need a focus. Driving Strike can be learned at level 1 and equipped from Character → Abilities.</p>${btn('nav-abilities','Review physical skills →','text-button')}`:''}<p class="modal-help">${i.channel?`Strike uses ${i.channel==='heavy'?'Might':i.channel==='precision'?'Finesse':'Intellect'} with this weapon. `:''}${i.focus?'This item enables focus-dependent spells. ':''}Equipment changes are available outside encounters and expeditions.</p><div class="modal-actions">${eq?btn('close','Keep equipped','primary'):!selected?'<p class="ability-reason">No compatible slot is available right now.</p>':btn('equip:'+id+':'+selected,'Equip in '+(SLOT_LABELS[selected]||selected),'primary',!owned||!!state.fight||!!state.delve||state.level<i.level)}${btn('close','Back','subtle')}</div>${slotCards}`,'EQUIPMENT COMPARISON');}
function slotChooser(slot){const currentId=state.gear?.[slot],current=currentId?resolved(currentId):null,locked=!!state.fight||!!state.delve;const choices=state.bag.map(id=>resolved(id)).filter(i=>i&&G.slotChoices(state,i.id).includes(slot));const occupied=slot==='offhand'&&resolved(state.gear.weapon)?.twoHanded;modal(`${SLOT_LABELS[slot]||G.SLOTS?.[slot]||slot} slot`,`${current?`<p>Equipped: <strong>${esc(current.name)}</strong>. Review another compatible item to compare before equipping.</p>`:'<p>This slot is empty. Choose gear you own to inspect its comparison before equipping.</p>'}${occupied?`<p class="ability-reason">Occupied by your two-handed ${esc(resolved(state.gear.weapon).name)}.</p>`:''}${choices.length?`<div class="slot-choice-list">${choices.map(i=>{const inSlot=currentId===i.id;return `<button data-action="slot-select:${i.id}:${slot}" class="slot-choice" ${locked||inSlot?'disabled':''}><span>${esc(i.name)}${inSlot?' · Equipped here':''}</span><small>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</small></button>`;}).join('')}</div>`:occupied?'<div class="empty-state">Your two-handed weapon occupies this slot.</div>':`<div class="empty-state">No compatible owned gear. Find equipment at the Quay market or earn it on a hunt.${btn('open-shop','Visit the market','text-button')}</div>`}<div class="modal-actions">${currentId?btn('compare:'+currentId,'Review current item','subtle'):''}${btn('close','Close','text-button')}</div>`, 'EQUIPMENT SLOT');}

function costLine(cost){const mats=Object.entries(cost?.materials||{}).map(([name,n])=>`${n} ${mat(name)}`).join(' + ');return [cost?.coins?`${cost.coins} coins`:null,mats||null].filter(Boolean).join(' + ')||'No cost';}
function exchangeOutput(recipe){return [...Object.entries(recipe.gain||{}).map(([name,n])=>`${n} ${mat(name)}`),...(recipe.gainItems||[]).map(id=>`1 ${resolved(id)?.name||id}`)].join(' + ')||'No listed reward';}
function costSources(cost){const mats=Object.keys(cost?.materials||{});return mats.length?mats.map(m=>`${mat(m)}: ${MATERIAL_SOURCES[m]||'Collect during hunts or use another exchange'}`).join('; '):'';}
function exchangeBlock(recipe){if(recipe.level&&state.level<recipe.level)return `Requires level ${recipe.level}.`;const owned=(recipe.gainItems||[]).find(id=>state.bag?.includes(id));return owned?`Already owned: ${resolved(owned)?.name||owned}.`:'';}
function exchangeCanAfford(recipe){return Object.entries(recipe.cost||{}).every(([m,n])=>(state.materials?.[m]||0)>=n)&&(state.coins||0)>=(recipe.coins||0);}
const MATERIAL_SOURCES={'Ledger scraps':'Nesting Rat Swarms','Canal iron':'Rummage Raccoons','Repair fittings':'Contracts and Sewing Kit exchanges','Salvaged fittings':'Duplicate gear and Sewing Kit exchanges','Runic residue':'Static Cling Wisps','Chainback shell':'Clawback Crabs','Stamped brass':'Lost & Found Appraiser hunts','Floodglass':'Chewster hunts and Sewing Kit exchanges','Floodglass Fragment':'The Spin Cycle, every clear'};
function missingCost(cost){const needs=[];if((cost?.coins||0)>state.coins)needs.push(`${cost.coins-state.coins} coins`);for(const [name,n] of Object.entries(cost?.materials||{})){const missing=n-(state.materials?.[name]||0);if(missing>0)needs.push(`${missing} ${mat(name)}`);}return needs.length?'Still need '+needs.join(' + '):'Ready to make';}
function workbenchStock(){const held=Object.entries(state.materials||{}).filter(([,n])=>n>0);return `<section class="workbench-stock" aria-label="Your Sewing Kit materials"><h3>${icon('supplies')} In your Sewing Kit</h3>${held.length?`<ul>${held.map(([name,n])=>`<li><strong>${n}</strong> ${esc(mat(name))}</li>`).join('')}</ul>`:'<p>No materials yet. Defeat a Nesting Rat Swarm for a guaranteed bit of Lint.</p>'}${btn('bag-tab:materials','Materials & hunting sources →','text-button')}</section>`;}
function firstWorkbenchProject(locked){if(state.bag.includes('cap'))return '';const recipe=G.EXCHANGES.craft_cap,sorting=G.EXCHANGES.ledger_fittings;return `<section class="workbench-project" aria-label="First crafting project">${itemArt('cap','large')}<div><span class="eyebrow">A FIRST PROJECT</span><h3>Make a ${esc(G.ITEMS.cap.name)}</h3><p>${esc(G.ITEMS.cap.desc)}</p><ol><li>Gather Lint from rat victories.</li><li>Review “${esc(sorting.name)}”: ${costLine({coins:sorting.coins,materials:sorting.cost})} makes 1 Spare thread.</li><li>Keep ${recipe.cost['Ledger scraps']} more Lint; combine it with the Spare thread and ${recipe.coins} coins to make your cap.</li><li>Find it in Satchel → Spare gear, then Compare & equip in Head.</li></ol><p>${esc(missingCost({coins:recipe.coins,materials:recipe.cost}))}</p><div class="workbench-project-actions">${btn('exchange:ledger_fittings','1. Review sorting','subtle',locked)}${btn('exchange:craft_cap','2. Review cap','primary',locked)}</div></div></section>`;}
function workbenchView(){const locked=!!state.fight||!!state.delve;const items=state.bag.map(id=>resolved(id)).filter(Boolean);const exchanges=Object.values(G.EXCHANGES||{});return `<section class="workbench-intro panel"><div class="panel-label">${renderServiceArt('toolkit',{size:'small'})}<span>SEWING KIT <span class="std">(WORKBENCH)</span></span></div><h2>Make what you have go further.</h2><p>Bring back materials from hunts, then turn them into gear or improve what you wear. Every victory supplies one material; equipment drops are separate. Choose a recipe or item, preview the result, then confirm the cost.</p><ol class="workbench-howto"><li><strong>Exchange</strong> Turn materials into Spare thread, Patches or new equipment.</li><li><strong>Upgrade</strong> Improve an owned item, up to +3.</li><li><strong>Reforge</strong> Choose a prefix or suffix; replace an existing mod of that kind.</li></ol><div class="coin-chip">${icon('coin')} ${state.coins} coins available</div>${locked?'<p class="locked-note">The Sewing Kit is closed until you return to town.</p>':''}</section>${workbenchStock()}${firstWorkbenchProject(locked)}<details class="workbench-section bench-group"><summary>${icon('materials')}Material exchanges<small>Convert materials or assemble gear</small></summary><div class="exchange-grid">${exchanges.map(recipe=>{const blocked=exchangeBlock(recipe);return `<article class="exchange-card"><div class="eyebrow">MATERIAL EXCHANGE</div><h3>${esc(recipe.name)}</h3><div class="exchange-flow"><div><small>USES</small><strong>${Object.entries(recipe.cost||{}).map(([m,n])=>`${n} ${esc(mat(m))}`).join(' + ')}</strong></div><span>→</span><div><small>MAKES</small><strong>${esc(exchangeOutput(recipe))}</strong></div></div><p class="material-hint">Source: ${Object.keys(recipe.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p><p class="explicit-cost">Cost: ${costLine({coins:recipe.coins,materials:recipe.cost})}</p>${costLedger({coins:recipe.coins,materials:recipe.cost})}<p class="workbench-availability">${blocked?esc(blocked):exchangeCanAfford(recipe)?'Ready to make':esc(missingCost({coins:recipe.coins,materials:recipe.cost}))}</p>${blocked?`<p class="ability-reason">${esc(blocked)}</p>`:''}${btn('exchange:'+recipe.id,blocked?'Unavailable · See reason':'Review exchange','subtle',locked||!!blocked)}</article>`;}).join('')}</div></details><details class="workbench-section bench-group"><summary>${icon('upgrade')}Upgrade or reforge gear<small>Inspect changes before spending</small></summary>${items.length?`<div class="workbench-items">${items.map(i=>{const up=G.upgradePreview(state,i.id);return `<article class="workbench-item"><div><span class="eyebrow">${SLOT_LABELS[i.slot]||G.SLOTS?.[i.slot]||i.slot} ${i.upgrade?`· +${i.upgrade}`:''}</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join(' · ')||esc(i.desc)}</p><small class="workbench-availability">${up.level>=3?'Upgrade cap reached':up.allowed?'Upgrade ready':up.reason==='You cannot afford this upgrade.'?esc(missingCost(up.cost)):esc(up.reason||'')}</small></div><div class="workbench-actions">${costSources(up.cost)?`<small class="material-hint">Upgrade material: ${esc(costSources(up.cost))}</small>`:''}${btn('upgrade:'+i.id,up.level>=3?'Preview upgrade · cap reached':`Preview upgrade · ${costLine(up.cost)}`,'subtle',locked)}${['prefix','suffix'].map(kind=>{const options=Object.values(kind==='prefix'?G.PREFIXES||{}:G.SUFFIXES||{}).filter(x=>x.slots?.includes(i.slot));return options.length?btn(`affix-menu:${i.id}:${kind}`,`Reforge ${kind}`,'text-button tiny',locked):'';}).join('')}</div></article>`;}).join('')}</div>`:'<div class="empty-state">Bring equipment back from a hunt to begin upgrading and reforging it.</div>'}</details>`;}
function vendorLabel(id){const v=M.VENDORS[M.classifyVendor(id)];return v?`${v.name} (${v.kind})`:'Quay market';}
function buyReview(id){const p=G.buyPreview(state,id),i=G.ITEMS[id];if(!i)return;modal(`Buy ${esc(i.name)}`,`<p>${esc(i.desc)}</p><div class="compare"><div><span class="eyebrow">ITEM</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">FULL PRICE</span><h3>${p.price} coins</h3><p>Coins on hand: ${state.coins}</p></div></div>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<p class="modal-help">Buying adds this item to your satchel. It does not equip it.</p><div class="modal-actions">${btn('buy-confirm:'+id,'Confirm purchase · '+p.price+' coins','primary',!p.allowed||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,esc(vendorLabel(id).toUpperCase())+' · PURCHASE REVIEW');}
function sellReview(id){const p=G.sellPreview(state,id),i=resolved(id);modal(`Sell ${esc(i.name)}`,`<p>This sale is for unequipped gear only. Its affixes and upgrades are removed with the item; no materials are returned.</p><div class="compare"><div><span class="eyebrow">ITEM TO SELL</span>${itemArt(i,'medium')}<h3>${esc(i.name)}</h3><p>${itemStats(i).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">COIN VALUE</span><h3>+${p.price} coins</h3><p>Coins on hand: ${state.coins} → ${state.coins+p.price}</p></div></div>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>${Object.values(state.gear).includes(id)?btn('open-gear','Go to Gear page to unequip','text-button'):''}`:''}<p class="modal-help">Nothing is removed and no coins are added until you confirm the sale.</p><div class="modal-actions">${btn('sell-confirm:'+id,'Confirm sale · +'+p.price+' coins','primary',!p.allowed||!!state.fight||!!state.delve)}${btn('close','Keep item','subtle')}</div>`,esc(vendorLabel(id).toUpperCase())+' · SALE REVIEW');}
function bagView(){
 const locked=!!state.fight||!!state.delve,ids=state.bag.filter(id=>!Object.values(state.gear).includes(id));
 const tabs=`<div class="tabs bag-tabs" aria-label="Satchel sections">${btn('bag-tab:gear',`${icon('gear')}Spare gear`,bagTab==='gear'?'active':'')}${btn('bag-tab:materials',`${icon('materials')}Materials`,bagTab==='materials'?'active':'')}${btn('bag-tab:workbench',`${icon('workbench')}Sewing Kit <span class="std">(Workbench)</span>`,bagTab==='workbench'?'active':'')}</div>`;
 const materials=`<section class="panel"><h3>${renderServiceArt('materials',{size:'small'})} Materials on hand</h3>${Object.keys(state.materials||{}).length?Object.entries(state.materials).map(([n,c])=>`<div class="material-row"><span>${esc(mat(n))}<small class="material-hint">${esc(MATERIAL_SOURCES[n]||'Collected during hunts and contracts')}</small></span><strong>${c}</strong></div>`).join(''):'<p class="muted">Complete a hunt to collect your first material.</p>'}<p class="mechanics">The Sewing Kit (Workbench) shows material sources and spends nothing until you confirm.</p>${btn('bag-tab:workbench',`${icon('workbench')}Open Sewing Kit (Workbench)`,'subtle')}</section>`;
 const inventory=`<div class="inventory-summary"><span>${ids.length} unequipped items</span>${btn('open-gear','Equipped slots','text-button')}</div>${locked?'<p class="ability-reason">Equipment changes are locked until the encounter or expedition ends.</p>':''}${ids.length?`<div class="item-grid">${ids.map(id=>{const i=resolved(id);return `<section class="item-card"><div class="item-card-top"><span class="item-symbol">${itemArt(i,'medium')}</span><div><h3>${esc(i.name)}</h3><small>${SLOT_LABELS[i.slot]||G.SLOTS[i.slot]} · Level ${i.level}</small></div></div><div class="item-stats">${itemStats(i).map(t=>`<span>${esc(t)}</span>`).join('')}</div><details class="item-lore"><summary>Details</summary><p>${esc(i.desc)}</p></details>${btn('compare:'+id,'Compare & equip','subtle')}</section>`;}).join('')}</div>`:`<section class="panel"><h3>Everything is in use.</h3><p>Your equipped gear is on the Character → Gear page. Find spare equipment through hunts, material exchanges, or the market.</p>${btn('nav:market',`${icon('market')}Visit Quay market`,'subtle')}</section>`}`;
 return shell(`<div class="satchel-page">${tabs}${bagTab==='materials'?materials:bagTab==='workbench'?workbenchView():inventory}</div>`,'Personal effects','Spare equipment, collected materials, and Sewing Kit (Workbench) services.','SATCHEL · FLUFFINGTON QUAY');
}
function marketView(){return shell(M.renderMarket(state,{vendorId,mode:shopMode}),'Quay market','Three specialists. Compare your options before spending.','TRADERS · FLUFFINGTON QUAY');}
function recordsTabs(){return `<div class="tabs records-tabs" aria-label="Records and help">${btn('nav:journal',`${icon('journal')}Chronicle`,view==='journal'?'active':'')}${btn('nav:world',`${icon('pin')}World`,view==='world'?'active':'')}${btn('nav:guide',`${icon('guide')}Field guide`,view==='guide'?'active':'')}</div>`;}
function worldView(){return shell(`${recordsTabs()}${renderWorldHub(state,{tab:worldTab})}`,'Beyond the Quay','Your local adventure, with room for a shared world.','WORLD RECORD · FUTURE CHAPTERS');}
function marketCompare(id,slot=null){const comparison=M.renderStockComparison(state,id,slot);if(comparison)modal(esc(comparison.title),comparison.body,'EQUIPMENT COMPARISON');}
function journalView(){return shell(`${recordsTabs()}<div class="layout"><div class="main-column">${state.pending!==null?`<div class="point-notice">A contract outcome is ready. ${btn('claim','Review →')}</div>`:''}<div style="padding:6px 0 0 5px">${state.journal.map(j=>`<article class="journal-entry ${j.kind}"><div class="eyebrow">${{story:'A NOTE IN YOUR STORY',growth:'VISIBLE PROGRESS',achievement:'MERIT BADGE EARNED (ACHIEVEMENT)',discovery:'A BUILD INTERACTION'}[j.kind]||'YOUR RECORD'}</div><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></article>`).join('')}</div></div><aside class="side-column">${titlePanel(`YOUR MERIT BADGES <span class="std">(ACHIEVEMENTS)</span> ${icon('crown')}`,state.achievements.length?state.achievements.map(a=>`<div class="achievement-card"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></div>`).join(''):'<h3>Notable, eventually.</h3><p>Rescue someone. Stand through a heavy attack. Interrupt a bad idea. The system keeps receipts.</p>')}${questPanel()}</aside></div>`,'A record worth keeping','Your choices, discoveries, and minor administrative triumphs.','THE CHRONICLE · YOUR ADVENTURE');}
const RULES=`<section class="guide-section"><h3>A slower story with smaller gains</h3><p>Minor contracts and major story milestones are accepted explicitly. Only qualifying victories after acceptance count toward their encounter objectives. Speak with Mara, report completed work, and take explicit story actions to move the chapter forward. Ordinary hunts always retain their own rewards.</p><p>Levels are split into four parts, called Stitches (level parts). Each completed Stitch grants one attribute point, and a full level is a Seam. Full levels use three times the earlier prototype XP, with no timed level gates or offline gains. The next part and next full level are both shown on your character sheet.</p></section><section class="guide-section"><h3>One tap. One exchange.</h3><p>The four-action row adapts to your weapon and equipped abilities. With Arc Bolt it offers Attack, Arc Bolt, Wardcast, and Hunker down (Defend); with Driving Strike it offers Attack, Driving Strike, Guardstrike, and Hunker down. A precision weapon with no shield swaps Guardstrike for Sidestep. Your action resolves first. If the enemy survives, it responds with the displayed intent. A shared 0.65-second delay follows every accepted combat action, including the final action of a fight. Switching buttons does not bypass it. Extra taps are ignored and never queued. The timer only re-enables controls: it never attacks, restores resources, or advances the game. The game never advances combat on a timer, while closed, or without an action.</p><p>Repeating a comfortable action is fine. Tougher encounters reward reading the intent. Fluff up at the Quay (Rest) is available outside combat. Your three resources are Stuffing (Health), Sparkle (Mana) and Bounce (Stamina). Every accepted action that spends no Sparkle restores 2 Sparkle, capped at your maximum. Attacks, Hunker down, and physical skills all count; spells do not. Hunker down (Defend) also restores 2 Bounce. Shake it off (Recover) trades one exchange for 10 Sparkle in total (8 recovery + 2 regeneration) and 10 Bounce while the enemy still responds. Waiting and rejected taps restore nothing. Fluffing up takes four seconds and needs a final tap to finish; it never heals automatically. A knockout puts you Back on the shelf (Defeated): it costs 5% of carried coins, capped at 50, and at least twelve seconds of drying off (Recovering). Levels and equipment stay safe.</p></section><section class="guide-section"><h3>Your compact action bar</h3><ul><li><strong>Attack:</strong> free weapon strike, physical damage. Sword scales with Might; blade with Finesse; rod with Intellect.</li><li><strong>Arc Bolt:</strong> 1.25× spell damage. Costs 16 Sparkle (mana), or 12 with its economy mastery, and needs a focus-tagged item.</li><li><strong>Wardcast:</strong> 0.85× spell damage and Guard together. Costs 16 Sparkle (mana) and 10 Bounce (stamina); requires a focus and shield. This is one budgeted action.</li><li><strong>Driving Strike:</strong> 1.15× physical weapon-channel damage for 10 Bounce (stamina). It does not require a focus.</li><li><strong>Guardstrike:</strong> 0.80× physical weapon-channel damage plus Guard for 12 Bounce (stamina). Requires a shield; no focus or Sparkle.</li><li><strong>Sidestep:</strong> 0.80× precision weapon-channel damage plus Guard for 12 Bounce (stamina). It replaces Guardstrike for a blade or other precision weapon with no shield; no focus or Sparkle.</li><li><strong>Hunker down (Defend):</strong> free Guard; prevents 35% of a hit this exchange, or 65% of a declared heavy attack.</li><li><strong>Opening:</strong> guarding a declared heavy (Hunker down, Brace, Guardstrike, Sidestep or Wardcast) opens the enemy. Your next exchange’s damaging action cannot glance and deals +25% damage; the larger of Opening and Expose applies, never both. It expires after one exchange whether used or not.</li><li><strong>Shake it off (Recover):</strong> restore 10 Sparkle (mana) in total (8 recovery + 2 regeneration) and 10 Bounce (stamina) before the enemy responds.</li><li><strong>Learned active abilities:</strong> Arc Bolt costs 16 Sparkle (12 with economy mastery) and begins learned. Brace costs 12 Bounce; Mend 24 Sparkle; Disrupt 16 Bounce. Driving Strike, Aegis, and Expose each have their own listed costs. Their unlock requirements appear on the Abilities tab.</li><li><strong>Brace:</strong> Guard plus a barrier for this exchange. Blocks use for the next 2 exchanges. Its barrier grows with mastery.</li><li><strong>Disrupt:</strong> weapon strike. An accurate hit cancels a heavy wind-up; target then has 3 exchanges of interrupt immunity. Blocks use for the next 3 exchanges.</li><li><strong>Mend:</strong> restore Stuffing (health) up to your maximum. Blocks use for the next 2 exchanges.</li><li><strong>Go still (Withdraw):</strong> freeze, take half the enemy response, slip away, and forfeit this fight’s rewards. Completed room rewards stay yours.</li></ul></section><section class="guide-section"><h3>Make a durable caster</h3><p>A new stuffie begins with Arc Bolt equipped and Prepared equipped as their passive. Reservoir unlocks at level 2 after one contract or two useful Guards; Sure Footing unlocks at level 2 after one contract. A useful Guard that prevents at least 20 hostile damage charges Reservoir. Your next Arc Bolt or Wardcast gains 10% raw spell damage. One charge maximum; it expires after the next exchange.</p><p>Try Hunker down (Defend) or Wardcast against the rats’ Nest rush, then cast. The Chronicle records the first successful interaction. Unlocks are shown on the Abilities tab; learned abilities must also be equipped before their action appears in combat.</p></section><section class="guide-section"><h3>Seven attributes, one build</h3><ul>${Object.entries(G.ATTRS).map(([k,[n,d]])=>`<li><strong>${n} (${k.toUpperCase()}):</strong> ${d}.</li>`).join('')}</ul><p>Each attribute starts at a minimum of 8. The level-1 budget begins at 68: 56 baseline points plus 12 invested in your starter build. Each of four parts in a level awards one attribute point. The character sheet shows current-part and full-level progress; every milestone can be allocated when convenient. A free respec returns the 12 discretionary starter points plus your level-up points. Gear bonuses are separate.</p><p>Old saves receive base Luck 8 without losing existing stats, unspent points, gear, or progress. Luck grants no extra turn, XP, or passive income.</p></section><section class="guide-section"><h3>The numbers behind the fiction</h3><p>Max Stuffing (Health) = <code>floor(200 + 12×level + 10×VIT + 4×WIL + brand bonus)</code><br>Sparkle (Mana) = <code>floor(30 + 2×WIL + INT + brand bonus)</code><br>Bounce (Stamina) = <code>floor(35 + 1.5×VIT + 1.5×FIN + brand bonus)</code></p><p>Raw strike = <code>item base + 0.9×power + 4</code>. Power = twice the scaling attribute + level. Arc Bolt uses spell power and its mastery rank. The focus offhand adds its spell base once, to spells.</p><p>Mitigation = <code>defense / (defense + 100 + 8×attacker level)</code>, capped at 65%. Armor protects from physical damage; ward from arcane. Critical hits deal 1.25× damage. Let <code>F = max(0, LCK−8) / (max(0, LCK−8)+40)</code>. Critical chance = <code>5% + 15%×FIN/(FIN+208) + 10%×F</code>, capped at 25%. Equipment-drop chance = <code>20% + 15%×F</code>. Critical chance is checked only on a solid hit. Insight no longer reduces critical chance. Accuracy is bounded at 65–98%; failed accuracy checks are glancing hits for 55% damage, to avoid empty clicks.</p><p>Enemies’ displayed raw intent damage is reduced by your equipment, then Guard and barriers. Armor or ward, Guard and barrier together never prevent more than 85% of one hit; only a successful interrupt cancels a response entirely. Sure Footing adds 8 evasion rating and uses that rating in the enemy’s bounded accuracy check. Enemy glancing hits deal 55% damage. The seal’s 15 barrier applies to its triggering exchange.</p></section><section class="guide-section"><h3>Progress that belongs to you</h3><p>Each of four parts in a level awards one attribute point. Level 10 is this prototype’s cap, at part 1. Free early respecs return all invested points. Equipment never changes your invested budget. Relevant equipped abilities earn at most one mastery mark each per completed eligible encounter, capped at three abilities. Mastery caps at rank 3. At rank 3, Arc Bolt chooses 9 Sparkle (mana) or 15% more damage; Brace chooses +15 barrier or a cooldown one exchange shorter; Disrupt chooses +15% damage or one less exchange of interrupt immunity; Mend chooses +15% healing or a cooldown one exchange shorter.</p><p>Enemies 3–5 levels below you award 60% XP; 6 or more below award 25%, with no mastery. Stronger eligible hunts give up to 25% extra XP. First contract completion is awarded once.</p><p>Every victory grants coins and one material, stored in Satchel → Materials. Equipment is a separate reward and is added to Satchel → Spare gear, ready to compare and equip. After five victories without equipment or salvage, the next victory guarantees an equipment reward; owned duplicates become Spare thread. This streak is saved with your character. Equipment drops start at 20%. Luck above 8 improves this chance with diminishing returns, approaching 35%. The roll chance is recorded when an encounter starts; duplicates become a Spare thread. The Copper-Thread Charm can drop from level 1 onward. The first boss clear gives a guaranteed item choice. Materials are collectible and used at the deterministic Sewing Kit (Workbench) for exchanges, gear, upgrades, and prefix/suffix reforges. Each operation shows its cost and result and asks for confirmation before spending. Random rarity tiers remain future work.</p></section><section class="guide-section"><h3>A first chapter, not a persistent world</h3><p>This is a solo, browser-local prototype based on your design pack. Progress is saved on this browser after each action. There is no account sync, multiplayer, server-verified economy, prestige, offline progress, or live AI narrator. B.U.R.S.A.R. (the Bureau of Unclaimed Residents, Stuffies And Repairs) speaks through each stuffie’s care tag. Its responses are authored and tied to recorded events.</p><p>The source includes your modular design files. Balance, combined-action costs, enemy numbers, glancing hits and ability unlock requirements are explicit prototype choices for playtesting.</p></section>`;
function guideSections(){let index=0;return RULES.replace(/<section class="guide-section"><h3>(.*?)<\/h3>([\s\S]*?)<\/section>/g,(_,title,body)=>`<details class="guide-section guide-topic" ${index++===0?'open':''}><summary>${icon('guide')}${title}</summary>${body}</details>`);}
function guideView(){return shell(`<div class="guide-page">${recordsTabs()}<div class="guide-tools">${titlePanel('YOUR SAVE',`<h3>Keep your receipts.</h3><p>Export a character to back it up or move devices. Import adds a character and preserves the current roster.</p><div class="save-controls">${btn('export','Export save','subtle')}${btn('import','Import a save','subtle')}</div><p class="tiny muted">Save format v4. Imports v1, v2, v3, and v4.</p>`)}${titlePanel('CHARACTERS',`<p>Keep up to six independent local adventures.</p>${btn('character-manager','Manage characters','subtle')}`)}${titlePanel('PLAYTEST LAB',`<p>Independent disposable characters; no campaign saves are read or changed.</p><a class="lab-launch-link" href="lab.html" target="_blank" rel="noopener">${icon('lab')}Open playtest lab ↗</a>`)}</div>${guideSections()}</div>`,'The fine print, legibly.','Rules, saves, and character management.','FIELD GUIDE · RULES & SAVES');}
function syncCombatDelay(){
clearTimeout(actionDelayTimer);
const controls=$('.combat-controls');if(!controls||!state.fight)return;
const remaining=G.actionDelayRemaining(state),waiting=remaining>0;
controls.classList.toggle('waiting',waiting);
for(const button of controls.querySelectorAll('[data-action^="combat:"]')){
 const key=button.dataset.action.split(':')[1],info=G.actionInfo(state,key);
 button.disabled=waiting||!!info.reason;
 button.title=info.reason||(waiting?'Brief action delay. Tap again when ready.':info.desc);
}
$('#action-ready-text').textContent=waiting?'Action recovery · next tap soon':'Ready for your next action';
$('#action-delay-count').textContent=waiting?(remaining/1000).toFixed(2)+'s':'Ready';
$('#action-delay-track').setAttribute('aria-valuenow',String(Math.max(0,G.ACTION_DELAY_MS-remaining)));
$('#action-delay-track').setAttribute('aria-valuetext',waiting?'Recovering · '+(remaining/1000).toFixed(2)+' seconds remaining':'Ready');
const track=controls.querySelector('.action-delay-track i');
track.style.setProperty('--action-wait',remaining+'ms');
if(waiting)actionDelayTimer=setTimeout(syncCombatDelay,remaining+10);
}
function newCharacterView(){return `<div class="new-character-page"><header class="wizard-brand">${icon('crown')}<span>Crown & Calamity</span><small>v0.11.0 · Fluffington Quay</small></header><main class="new-character-content">${Creator.renderCharacterCreator({draft:creationDraft})}${btn('import','Import an existing adventure','text-button full-width')}</main></div>`;}
function storyView(){return shell(renderStory(state),'The work beneath the Quay','Minor jobs establish the problem. Major contracts change the story.','CHAPTER I · STORY & CONTRACTS');}
function render(){save();$('#app').innerHTML=firstRun?newCharacterView():({hunt:huntView,story:storyView,character:characterView,bag:bagView,market:marketView,journal:journalView,guide:guideView,world:worldView}[view])();syncCombatDelay();syncRecoveryUI();exchangeFeedback=null;}
function modal(title,body,eyebrow='STUFFIE SERVICES'){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button data-action="close" class="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();}
function close(){if($('#modal').open)$('#modal').close();}
function showStoryNudge(){const next=getStoryNudge(state);if(!next){close();view='story';render();return;}if(next.kind==='progress'){close();view='story';render();return;}const c=next.contract;let actions='';if(next.kind==='report'){actions=btn(`story-claim:${c.id}:coins`,'Report to Mara · collect reward','primary');if(c.id==='drainage_inspection')actions+=btn(`story-claim:${c.id}:materials`,'Help repairs · 10 coins + 3 Patches','subtle');}else if(next.kind==='action')actions=btn('story-action:'+next.step.id,esc(next.step.label),'primary');else actions=btn('story-accept:'+c.id,'Accept this '+c.kind+' contract','primary');modal(next.kind==='accept'?'Next contract: '+esc(next.title):esc(next.title),`<p>${esc(next.text)}</p>${c?`<ul class="story-objectives">${c.objectives.map(o=>`<li><span>${esc(o.label)}</span><strong>${o.current} / ${o.target}</strong></li>`).join('')}</ul><p>Contract reward: ${c.reward.xp} XP · ${c.reward.coins} coins${Object.entries(c.reward.materials||{}).map(([m,n])=>` · ${n} ${esc(mat(m))}`).join('')}</p>`:''}<div class="modal-actions">${actions}${btn('close','Stay at the hunt','text-button')}</div>`,'YOUR NEXT STORY STEP');}
function claim(){if(state.pending==='bossLoot'){modal('A choice, duly earned.',`<p>The Spin Cycle is relieved of duty. Choose one guaranteed first-clear reward. Both can support a build; neither binds your future.</p><div class="choices">${['seal','band'].map(id=>btn('boss-loot:'+id,`<strong>${resolved(id).name}</strong><small>${resolved(id).desc}</small>`,'choice')).join('')}</div>`,'CHAPTER COMPLETE · BELOW THE RINSE LINE');return;}view='story';close();render();window.scrollTo({top:0});}

function equipmentEffectPreview(id,targetSlot=null){const item=resolved(id),slot=targetSlot||(G.slotChoices?.(state,id)||[item.slot]).find(x=>!state.gear[x])||(G.slotChoices?.(state,id)||[item.slot])[0];if(!slot)return '';const before=G.totals(state),gear={...state.gear,[slot]:id};for(const [k,v] of Object.entries(gear))if(k!==slot&&v===id)gear[k]=null;if(item.twoHanded)gear.offhand=null;const after=G.totals({...state,gear});const names={hp:'Max Stuffing (Health)',mp:'Max Sparkle (Mana)',sp:'Max Bounce (Stamina)',armor:'Armor',ward:'Ward',heavyPower:'Heavy power',precisionPower:'Precision power',spellPower:'Spell power',physicalAcc:'Physical accuracy',spellAcc:'Spell accuracy',evasion:'Evasion',critChance:'Critical chance',equipmentDropChance:'Equipment drops'};const changes=Object.entries(names).filter(([key])=>before[key]!==after[key]);return changes.length?`<h3>What changes for your build</h3><div class="equipment-effects">${changes.map(([key,name])=>`<p><strong>${name}</strong><br>${['critChance','equipmentDropChance'].includes(key)?percent(before[key]):before[key]} → ${['critChance','equipmentDropChance'].includes(key)?percent(after[key]):after[key]}</p>`).join('')}</div>`:'';}
function costLedger(cost){const rows=[];if(cost?.coins)rows.push(`Coins: ${state.coins} / ${cost.coins}`);for(const [m,n] of Object.entries(cost?.materials||{}))rows.push(`${mat(m)}: ${state.materials?.[m]||0} / ${n}`);return rows.length?`<p class="cost-ledger">On hand · ${rows.map(esc).join(' · ')}</p>`:'';}
function bonusLabels(bonus={}){return [...Object.entries(bonus).filter(([k])=>k!=='stats').map(([k,v])=>`${v} ${k}`),...Object.entries(bonus.stats||{}).map(([k,v])=>`${v} ${G.ATTRS[k]?.[0]||k}`)].join(' · ')||'No listed bonus';}
function previewPair(title,p,confirmAction,eyebrow='SEWING KIT PREVIEW'){const before=p?.before,after=p?.after,price=costLine(p?.cost);modal(title,`<p class="explicit-cost"><strong>Cost to confirm: ${esc(price)}</strong></p>${costLedger(p?.cost)}${costSources(p?.cost)?`<p class="material-hint">Source: ${esc(costSources(p.cost))}</p>`:''}<div class="compare"><div><span class="eyebrow">BEFORE</span>${before?itemArt(before,'large'):''}<h3>${esc(before?.name||'Current item')}</h3><p>${itemStats(before||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div><div><span class="eyebrow">AFTER</span>${after?itemArt(after,'large'):''}<h3>${esc(after?.name||'Updated item')}</h3><p>${itemStats(after||{}).map(esc).join('<br>')||'No listed bonuses.'}</p></div></div>${p?.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<p class="modal-help">No currency or materials are spent until you confirm below.</p><div class="modal-actions">${btn(confirmAction,'Confirm and spend','primary',!p?.allowed||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,eyebrow);}
function openExchange(id){const r=G.EXCHANGES?.[id];if(!r)return;const block=exchangeBlock(r),can=exchangeCanAfford(r);modal(r.name,`<div class="exchange-flow"><div><small>YOU GIVE</small><strong>${Object.entries(r.cost||{}).map(([m,n])=>`${n} ${esc(mat(m))}`).join(' + ')}</strong></div><span>→</span><div><small>YOU RECEIVE</small><strong>${esc(exchangeOutput(r))}</strong></div></div><p>Source: ${Object.keys(r.cost||{}).map(m=>esc(MATERIAL_SOURCES[m]||'Hunts and contracts')).join('; ')}</p>${block?`<p class="ability-reason">${esc(block)}</p>`:''}<p class="explicit-cost"><strong>Cost: ${costLine({coins:r.coins,materials:r.cost})}</strong></p>${costLedger({coins:r.coins,materials:r.cost})}<div class="modal-actions">${btn('exchange-confirm:'+id,'Confirm exchange','primary',!can||!!block||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>`,'MATERIAL EXCHANGE');}
function openAffixMenu(id,kind){const item=resolved(id),list=kind==='prefix'?G.PREFIXES:G.SUFFIXES;const candidates=Object.values(list||{}).filter(x=>x.slots?.includes(item.slot));modal(`Reforge ${item.name}`,`<p>Choose a ${kind} to preview. An existing ${kind} will be replaced only after you confirm the new cost.</p><div class="affix-options">${candidates.map(x=>{const p=G.affixPreview(state,id,kind,x.id);return `<button data-action="affix-preview:${id}:${kind}:${x.id}" class="affix-option" ${!!state.fight||!!state.delve?'disabled':''}><strong>${esc(x.name)}</strong><small>${bonusLabels(x.bonus)}</small><small>Cost: ${costLine(p.cost)}</small>${costSources(p.cost)?`<small>Source: ${esc(costSources(p.cost))}</small>`:''}${p.reason?`<small>${esc(p.reason)}</small>`:''}</button>`;}).join('')}</div><div class="modal-actions">${btn('close','Back','subtle')}</div>`,'CHOOSE A REFORGE');}
function exportSave(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`crown-calamity-level-${state.level}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep it somewhere dry.');}
function identity(){const d=identityDraft||{name:state.name,origin:state.origin,appearance:{...state.appearance}};identityDraft=d;const lineage=state.raceId?RACES[state.raceId]:null;modal('Your name on the paperwork.',`<label>Stuffie name<input id="name-input" maxlength="32" value="${esc(d.name)}" autocomplete="off"></label><label>Background<input id="origin-input" maxlength="70" value="${esc(d.origin)}"></label><p>${esc(lineage?.name||state.race)}${lineage?' · '+esc(lineage.passiveName)+': '+esc(lineage.passiveDescription):' · Earlier ledger: your invested attributes are preserved.'}</p>${Creator.renderAppearanceEditor(state,{draft:d})}${!lineage?`<section class="heritage-adoption"><h3>Choose your brand</h3><p>Older stuffies can adopt one brand passive without resetting their attributes, equipment, or story. This choice is permanent; appearance can be changed later.</p><label>Brand<select id="heritage-input">${Object.values(RACES).map(r=>`<option value="${r.id}">${esc(r.name)} · ${esc(r.passiveName)}</option>`).join('')}</select></label>${btn('heritage-review','Review brand','subtle')}</section>`:''}<div class="modal-actions">${btn('save-identity','Save identity & appearance','primary')}${btn('close','Cancel','subtle')}</div>`,'STUFFIE RECORD');}
async function act(action){const parts=action.split(':'),[a,b,c]=parts,d=parts.slice(3).join(':');if(a==='close'){close();return;}if(a==='story-next'){showStoryNudge();return;}if(a==='creator-race'){readCreationDraft();if(RACES[b])creationDraft=Creator.normalizeCreationDraft({...creationDraft,race:b});refreshCreator();return;}if(a==='creator-kit'){readCreationDraft();if(G.STARTER_KITS[b])creationDraft=Creator.normalizeCreationDraft({...creationDraft,kit:b});refreshCreator();return;}if(a==='heritage-review'){const id=$('#heritage-input').value,r=RACES[id];if(!r)return;modal('Adopt '+esc(r.name)+'?',`<p>${esc(r.passiveName)}: ${esc(r.passiveDescription)}</p><p>${esc(r.bursarReading||'')}</p><p>Your current attributes stay as invested. Only the brand passive is added. This is the one-time choice for this older stuffie.</p><div class="modal-actions">${btn('heritage-confirm:'+id,'Adopt this brand','primary')}${btn('close','Keep my current record','subtle')}</div>`,'BRAND REVIEW');return;}if(a==='heritage-confirm'){if(G.adoptRace(state,b)){close();identityDraft=null;render();toast('Brand recorded. Your adventure and attributes stay yours.');}else toast('A brand can be chosen once, outside combat and recovery.');return;}if(a==='relic-unlock'){const p=G.unlockRelicPreview(state,b);modal('Open keychain loop '+(Number(b)+1)+' (echo socket)',`<p>A permanent extra relic loop. It does not include a relic license.</p><p><strong>Cost: ${p.coinCost} coins</strong> · On hand: ${state.coins}</p>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<div class="modal-actions">${btn('relic-unlock-confirm:'+b,'Unlock socket · '+p.coinCost+' coins','primary',!p.allowed)}${btn('close','Cancel','subtle')}</div>`,'RELIC RESONANCE');return;}if(a==='relic-unlock-confirm'){const r=G.unlockRelic(state,b);if(r.ok){close();render();toast('Keychain loop opened. Choose an owned relic to attune.');}else toast(r.reason);return;}if(a==='relic-attune'){const p=G.attuneRelicPreview(state,b,c);modal('Attune '+esc(p.name||'relic'),`<p>${itemArt(c,'large')}</p><p>Effect strength: ${(p.effectScale*100).toFixed(1)}% of flat bonuses. Unique core effects do not repeat.</p><p><strong>Cost: ${p.coinCost} coins</strong> · On hand: ${state.coins}</p><p>The license belongs to this socket permanently. Reattuning a licensed copy here is free; another socket needs its own copy. Next new same-type license: ${p.nextCost} coins.</p>${p.reason?`<p class="ability-reason">${esc(p.reason)}</p>`:''}<div class="modal-actions">${btn('relic-attune-confirm:'+b+':'+c,p.coinCost?'License & attune · '+p.coinCost+' coins':'Reattune owned copy','primary',!p.allowed)}${btn('close','Cancel','subtle')}</div>`,'RELIC ATTUNEMENT');return;}if(a==='relic-attune-confirm'){const r=G.attuneRelic(state,b,c);if(r.ok){G.capResources(state);close();render();toast('Relic echo attuned.');}else toast(r.reason);return;}if(a==='relic-clear'){const r=G.clearRelic(state,b);if(r.ok){G.capResources(state);render();toast('Echo cleared. The paid license stays with its loop.');}else toast(r.reason);return;}if(a==='social-open'){socialOpen=true;socialTab=['chat','friends','guilds','holdings'].includes(b)?b:'chat';render();$('#social-close')?.focus();return;}if(a==='social-close'){socialOpen=false;render();$('#social-toggle')?.focus();return;}if(a==='social-tab'){if(['chat','friends','guilds','holdings'].includes(b))socialTab=b;render();$('[data-action="social-tab:'+socialTab+'"]')?.focus();return;}if(a==='world-tab'){if(['world','friends','guilds','holdings'].includes(b))worldTab=b;view='world';render();$('[data-action="world-tab:'+worldTab+'"]')?.focus();return;}if(a==='create-character'||a==='creator-submit'){const draft=readCreationDraft(),{race,kit,appearance}=draft,name=draft.name.trim(),origin=draft.origin.trim()||'Former Gutter Canal surveyor';const created=C.createRosterCharacter(roster,{name,race,origin,kit,appearance},state);if(!created){toast(roster.characters.length>=C.MAX_CHARACTERS?'All six character slots are in use.':'Choose a valid name, brand, background, and starter kit. Character creation is unavailable during a fight or delve.');return;}state=created.state;firstRun=false;creationInModal=false;creationDraft=Creator.defaultCreationDraft();view='story';huntTab='hunts';charTab='overview';close();render();window.scrollTo({top:0});return;}if(a==='character-manager'){characterManager();return;}if(a==='new-character-form'){creationDraft=Creator.defaultCreationDraft();if(roster.characters.length>=C.MAX_CHARACTERS){toast('All six character slots are in use.');return;}newCharacterModal();return;}if(a==='switch-character'){const next=C.switchCharacter(roster,b,state);if(!next){toast(state.fight||state.delve?'Characters cannot be switched during a fight or delve.':'Character could not be switched.');return;}state=next;firstRun=false;view='hunt';huntTab=state.delve?'delve':'hunts';charTab='overview';close();render();toast(`${state.name} is now active.`);return;}if(a==='char-tab'){ charTab=b;render();window.scrollTo({top:0});return;}if(a==='slot'){slotChooser(b);return;}if(a==='slot-select'){compare(b,c);return;}if(a==='open-gear'){view='character';charTab='gear';render();close();window.scrollTo({top:0});return;}if(a==='nav-abilities'){view='character';charTab='abilities';close();render();window.scrollTo({top:0});return;}if(a==='open-shop'){view='market';shopMode='buy';render();close();window.scrollTo({top:0});return;}if(a==='nav'){if(!nav().some(([id])=>id===b))return;close();view=b;render();window.scrollTo({top:0});return;}if(a==='rest'){const r=G.restStatus(state);if(r.active){if(G.finishRest(state)){render();toast('Ready for another unreasonable errand.');}else toast('Still fluffing up. Finish when the countdown ends.');}else if(G.beginRest(state)){render();toast('Fluffing up started. Finish in a moment to restore your resources.');}else toast(state.fight||state.delve?'Fluffing up (Rest) is available outside encounters and expeditions.':'Your resources are already full.');return;}if(a==='cancel-rest'){G.cancelRest(state);render();toast('Fluffing up cancelled. No resources restored.');return;}
if(a==='story-accept'){if(G.acceptContract(state,b)){close();render();toast('Contract accepted. Your objectives now track completed actions.');}else toast('This contract is not available yet, or you are in an encounter.');return;}
if(a==='story-action'){const receipt=G.storyAction(state,b);if(receipt){render();modal('At the lower stair',`<p>${esc(receipt.text)}</p><div class="modal-actions">${btn('story-next','Next story step →','primary')}</div>`,'BELOW THE RINSE LINE');}else toast('Complete the listed objective before taking this story step.');return;}
if(a==='story-claim'){const receipt=G.claimContract(state,b,c);if(receipt){render();toast(`${G.STORY_CONTRACTS[b].kind==='major'?'Story milestone':'Minor contract'} completed · +${receipt.xp} XP · +${receipt.coins} coins.`);showStoryNudge();}else toast('This contract is not ready to report.');return;}
if(a==='story-delve'){view='hunt';huntTab='delve';state.last=null;render();window.scrollTo({top:0});return;}
if(a==='hunt-special'){if(state.delve){toast('Finish or leave the delve before hunting.');return;}if(G.startFight(state,b,'hunt',Date.now(),{special:true})){view='hunt';huntTab='hunts';render();focusEncounter();}else toast('That Special Edition hunt is not available right now.');return;}
if(a==='hunt'){if(state.delve){toast('Finish or leave the delve before hunting.');return;}if(G.startFight(state,b)){view='hunt';huntTab='hunts';render();focusEncounter();}else toast(G.restStatus(state).active?'Finish or cancel your fluffing up before hunting.':G.restStatus(state).wounded?'You are still drying off (Recovering). Give it a moment before you set out.':state.hp<=0?'Fluff up at the Quay (Rest) before setting out.':'This hunt is not available yet.');return;}
if(a==='combat'){const beforeMana=state.mp,before=state.discoveries.length,beforeNudge=getStoryNudge({...state,fight:null})?.key;const result=G.exchange(state,b);if(!result.ok){toast(result.reason);return;}exchangeFeedback={...result,action:b,manaRestored:Math.max(0,state.mp-beforeMana)};render();if(state.discoveries.length>before)toast('Interaction discovered: Stored Pressure. Recorded in your Chronicle.');if(result.victory||result.defeat||result.withdraw)window.scrollTo({top:0});if(result.victory&&state.pending!=='bossLoot'){const next=getStoryNudge(state);if(next&&next.kind!=='progress'&&next.key!==beforeNudge)showStoryNudge();}return;}
if(a==='toggle-log'){state.settings.details=!state.settings.details;render();return;}if(a==='mechanics'){modal('Every action, accounted for.',`<p>Attack is free. Cast spends 16 Sparkle (mana), or 12 with its economy mastery. Wardcast also spends 10 Bounce (stamina). Hunker down (Defend) is free, prevents 35% of a hit (65% of a declared heavy, which also grants Opening: +25% damage and no glancing on your next damaging action), and restores 2 Bounce after the enemy response. Each tap resolves just this exchange. A shared 0.65-second delay follows accepted actions. Extra taps during that pause are ignored, not queued.</p><p>Actions that spend no Sparkle restore 2 Sparkle, capped at your maximum. Shake it off (Recover) restores 10 Sparkle total (8 recovery + 2 regeneration) and 10 Bounce; the enemy still acts. Brace, Disrupt, and Mend show remaining cooldown exchanges on their buttons. A blocked action spends no turn.</p><p>Reservoir needs Guard to prevent at least 20 damage. It stores one +10% spell charge for the next exchange only.</p><div class="modal-actions">${btn('close','Back to the encounter','primary')}${btn('open-guide','All the rules →','subtle')}</div>`,'COMBAT REFERENCE');return;}
if(a==='open-guide'){close();view='guide';render();window.scrollTo({top:0});return;}if(a==='tab'){huntTab=b;state.last=null;render();return;}if(a==='clear-outcome'){state.last=null;render();return;}if(a==='delve-show'){state.last=null;huntTab='delve';render();return;}if(a==='delve-start'){if(G.startDelve(state)){huntTab='delve';render();}return;}if(a==='delve'){if(G.delveAction(state,b)){state.last=null;render();if(state.fight)focusEncounter();else window.scrollTo({top:0});if(b==='rest')toast('Camp used. Resources fully restored.');}return;}if(a==='delve-leave'){modal('Return to town?',`<p>Your completed room rewards stay yours. This run ends, and its camp and rooms reset on your next entry.</p><div class="modal-actions">${btn('confirm-leave','Return to the Quay','primary')}${btn('close','Stay in the Laundry Works','subtle')}</div>`);return;}if(a==='confirm-leave'){G.delveAction(state,'leave');close();render();return;}
if(a==='claim'){claim();return;}if(a==='quest'){if(G.completeQuest(state,b)){close();render();toast('Contract completed. Rewards and your choice recorded.');}return;}if(a==='boss-loot'){if(G.chooseBossLoot(state,b)){close();render();toast(`${resolved(b).name} added to your satchel.`);showStoryNudge();}return;}
if(a==='stat'){if(G.allocate(state,b)){render();}return;}if(a==='kit'){if(G.practice(state,b)){render();toast('Owned starter gear and its matching skill are prepared. Your attributes stay yours.');}return;}if(a==='passive'){if(G.equipAbility(state,b)){render();toast('Passive equipped.');}else toast(G.abilityStatus(state,b)?.reason||'Passive cannot be equipped.');return;}
if(a==='ability-learn'){if(G.learnAbility(state,b)){render();toast(`${G.ABILITIES[b].name} learned.`);}else toast(G.abilityStatus(state,b)?.reason||'Requirements are not met.');return;}if(a==='ability-equip'){if(G.equipAbility(state,b)){render();toast(`${G.ABILITIES[b].name} equipped.`);}else toast(G.abilityStatus(state,b)?.reason||'Ability cannot be equipped.');return;}if(a==='ability-remove'){if(G.unequipAbility(state,b)){render();toast(G.ABILITIES[b].kind==='passive'?`${G.ABILITIES[b].name} removed from the passive slot.`:`${G.ABILITIES[b].name} removed from the active bar.`);}return;}if(a==='mastery'){if(G.chooseMastery(state,b,c)){render();toast('Mastery choice recorded.');}return;}if(a==='identity'){identityDraft=null;identity();return;}if(a==='save-identity'){if(state.fight||state.delve)return;const n=$('#name-input').value.trim();if(!n){$('#name-input').focus();toast('Your name cannot be blank.');return;}state.name=n.slice(0,32);state.appearance=normalizeAppearance(state.raceId||resolveRace(state.race)?.id,identityDraft?.appearance||state.appearance);state.origin=$('#origin-input').value.trim().slice(0,70)||'Stuffie of Fluffington Quay';close();render();return;}
if(a==='respec'){modal('Reconsider your unreasonable choices.',`<p>Return all invested attributes to 8 and reclaim ${earnedAttributeBudget(state)-56} points to allocate. Equipment and learned mastery stay yours. Current resources will be capped to your revised limits.</p><div class="modal-actions">${btn('confirm-respec','Reallocate for free','primary')}${btn('close','Keep this build','subtle')}</div>`,'FREE EARLY RESPEC');return;}if(a==='confirm-respec'){if(G.resetStats(state)){close();render();}return;}
if(a==='shop-luck'){view='market';vendorId='curio';shopMode='buy';render();window.scrollTo({top:0});return;}if(a==='bag-tab'){if(b==='shop'){view='market';shopMode='buy';}else{view='bag';bagTab=b;}render();return;}if(a==='vendor'){if(M.VENDORS[b]){vendorId=b;render();}return;}if(a==='market-compare'){marketCompare(b,c);return;}if(a==='shop-tab'){if(['buy','sell'].includes(b))shopMode=b;render();return;}if(a==='compare'){compare(b);return;}if(a==='equip'){if(G.equip(state,b,c)){close();render();toast(`${resolved(b).name} equipped in ${SLOT_LABELS[c||resolved(b).slot]||c||resolved(b).slot}.`);}return;}if(a==='unequip-slot'){if(G.unequip(state,b)){render();toast(`${SLOT_LABELS[b]||b} slot emptied.`);}return;}if(a==='exchange'){openExchange(b);return;}if(a==='exchange-confirm'){const r=G.exchangeMaterials(state,b);if(r){close();render();toast(r.gainedItems?.length?`${r.gainedItems.map(id=>resolved(id)?.name||id).join(', ')} added to your satchel.`:'Materials exchanged. The receipt is in your satchel.');}else toast('Exchange unavailable: check the listed materials and coins.');return;}if(a==='upgrade'){const p=G.upgradePreview(state,b);previewPair(`Upgrade ${resolved(b).name}`,p,'upgrade-confirm:'+b);return;}if(a==='upgrade-confirm'){if(G.upgradeItem(state,b)){close();render();toast(`${resolved(b).name} upgraded.`);}return;}if(a==='affix-menu'){openAffixMenu(b,c);return;}if(a==='affix-preview'){const p=G.affixPreview(state,b,c,d);previewPair(`Apply ${G[c==='prefix'?'PREFIXES':'SUFFIXES']?.[d]?.name||'affix'}`,p,`affix-confirm:${b}:${c}:${d}`,'REFORGE PREVIEW');return;}if(a==='affix-confirm'){if(G.applyAffix(state,b,c,d)){close();render();toast(`${resolved(b).name} reforged.`);}return;}if(a==='buy-preview'){buyReview(b);return;}if(a==='buy-confirm'){if(G.buy(state,b)){close();render();toast(`${resolved(b).name} added to your satchel. Compare it before equipping.`);}else toast(G.buyPreview(state,b)?.reason||'Purchase unavailable.');return;}if(a==='sell-preview'){sellReview(b);return;}if(a==='sell-confirm'){const itemName=resolved(b)?.name||'Item',receipt=G.sell(state,b);if(receipt){close();render();toast(`${itemName} sold for ${receipt.coins} coins.`);}else toast(G.sellPreview(state,b)?.reason||'Sale unavailable.');return;}
if(a==='export'){exportSave();return;}if(a==='import'){modal('Add an adventure to your roster.',`<p>This save will be added as a new character. Your current character and roster stay saved. You can keep up to ${C.MAX_CHARACTERS} characters on this browser.</p><input id="save-file" class="file-input" type="file" accept="application/json,.json" aria-label="Choose save file"><div class="modal-actions">${btn('confirm-import','Import as new character','primary',roster.characters.length>=C.MAX_CHARACTERS||!!state.fight||!!state.delve)}${btn('close','Cancel','subtle')}</div>${roster.characters.length>=C.MAX_CHARACTERS?'<p class="ability-reason">All character slots are in use.</p>':''}`,'SAVE MANAGEMENT');return;}
if(a==='confirm-import'){const f=$('#save-file').files[0];if(!f){toast('Choose a save file first.');return;}if(f.size>2e6){toast('That file is too large to be a save.');return;}const created=C.importRosterCharacter(roster,await f.text(),state);if(!created){toast(roster.characters.length>=C.MAX_CHARACTERS?'All six character slots are in use.':'This save could not be imported right now.');return;}state=created.state;firstRun=false;close();view='hunt';charTab='overview';huntTab=state.delve?'delve':'hunts';render();toast('Save imported as a new character. Your previous adventures remain in the roster.');return;}
if(a==='reset'){characterManager();return;}}
document.addEventListener('input',e=>{const key=e.target.dataset?.creatorField;if(key==='name'||key==='origin')creationDraft={...creationDraft,[key]:e.target.value};});
document.addEventListener('change',e=>{const key=e.target.dataset?.creatorField;if(!key)return;if(key.startsWith('appearance-')){identityDraft=identityDraft||{name:state.name,origin:state.origin,appearance:{...state.appearance}};identityDraft.name=$('#name-input')?.value??identityDraft.name;identityDraft.origin=$('#origin-input')?.value??identityDraft.origin;identityDraft.appearance=normalizeAppearance(state.raceId||resolveRace(state.race)?.id,{...identityDraft.appearance,[key.slice(11)]:e.target.value});identity();return;}readCreationDraft();if(['race','kit'].includes(key))creationDraft=Creator.normalizeCreationDraft({...creationDraft,[key]:e.target.value});else if(APPEARANCE_OPTIONS[key])creationDraft=Creator.normalizeCreationDraft({...creationDraft,appearance:{...creationDraft.appearance,[key]:e.target.value}});if(key!=='name'&&key!=='origin')refreshCreator();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){try{Promise.resolve(act(b.dataset.action)).catch(err=>{console.error(err);toast('That action could not be completed. Your last saved progress is safe.');});}catch(err){console.error(err);toast('That action could not be completed.');}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&socialOpen){e.preventDefault();act('social-close');return;}if(e.repeat&&e.target.closest('[data-action^="combat:"]'))e.preventDefault();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
document.addEventListener('change',e=>{if(e.target.id==='inspect-target'&&G.ENEMIES.some(x=>x.id===e.target.value)){state.settings.inspectTarget=e.target.value;render();$('#inspect-target')?.focus();}});
if(state.delve)huntTab='delve';render();if(state.fight)focusEncounter();
